function show(html){modal.innerHTML=html;modal.showModal();modal.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>modal.close())}
async function mutate(url,method,data,message){try{state=await api(url,method,data);if(modal.open)modal.close();render();toast(message)}catch(e){if(e.code==='OVERLAPPING_BOOKING'){confirmOverlapDialog(e.message,()=>mutate(url,method,{...data,confirmOverlap:true},message));return}const err=modal.querySelector('.error');if(err)err.textContent=e.message;else toast(e.message)}}
function confirmOverlapDialog(message,onConfirm){show(`<h2>Passens tider överlappar</h2><p class="info-text">${esc(message)}</p><p>Det går bra att delta i båda passen, till exempel morgonpass och öppet hus, om du kan vara kvar.</p><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Avbryt</button><button class="primary" id="confirm-overlap">Ja, bekräfta överlappningen</button></div>`);$('#confirm-overlap').onclick=async()=>{const button=$('#confirm-overlap');button.disabled=true;try{await onConfirm()}finally{if(button.isConnected)button.disabled=false}}}
function slotDialog(id){
 const s=state.slots.find(x=>x.id===id),admin=isAdmin(state.user),b=state.bookings.find(x=>x.slot_id===id&&x.user_id===state.user.id),canCancel=admin||new Date(s.date+'T'+s.start)-Date.now()>=86400000,ended=new Date(s.date+'T'+s.end)<=new Date();
 show(`<div class="eyebrow">${fmt(s.date,{weekday:'long',day:'numeric',month:'long'})}</div><h2>${esc(s.title)}</h2><p>${s.start}–${s.end} · ${esc(staffing(s))}</p><p class="experience-status ${s.green_booked>0?'has-experience':'needs-experience'}">${experienceLabel(s)}</p><p class="info-text muted">${esc(s.note)}</p>${cleaningNote(s.date)}${s.extra_info?`<section class="notice"><strong>Extra information</strong><p class="info-text">${esc(s.extra_info)}</p></section>`:''}${admin?`<h3>Bokade volontärer</h3>${state.bookings.filter(x=>x.slot_id===id).map(x=>`<div class="list-row"><span>${esc(x.name)}</span>${!s.cancelled?`<button class="danger" data-cancel="${x.id}">Avboka</button>`:''}</div>`).join('')||'<p class="small">Ingen bokad ännu.</p>'}${!past(s)&&!s.cancelled?`<label>Boka åt volontär<select id="book-user">${state.users.filter(u=>u.active&&!state.bookings.some(x=>x.slot_id===id&&x.user_id===u.id)).map(u=>`<option value="${u.id}">${esc(u.name)}</option>`).join('')}</select></label><button id="admin-book">Boka vald volontär</button>`:''}`:''}<p class="error" role="alert"></p>${b&&!canCancel&&!s.cancelled?'<p class="notice">Mindre än 24 timmar kvar. Kontakta katthemmets bemanningsgrupp i Messenger för avbokning.</p>':''}<div class="dialog-actions">${admin&&!ended?`<button id="extra-info">${s.volunteer_meeting?'Information om träffen':'Extra information'}</button>`:''}${admin&&s.kind!=='open_house'&&!ended?`<button id="edit-slot">${s.cancelled?'Boka om':'Ändra / boka om'}</button>${!s.cancelled?'<button class="danger" id="cancel-slot">Ställ in</button>':''}`:''}${!past(s)&&!s.cancelled&&s.kind==='regular'?`<button id="recurring-book">${admin?'Boka återkommande åt vald volontär':'Boka återkommande'}</button>`:''}${admin&&!past(s)&&!s.cancelled&&s.kind==='regular'?'<button id="recurring-self">Boka återkommande</button>':''}${calendarLink(s)}<button data-close>Stäng</button>${!s.cancelled?(b?`<button class="danger" id="cancel" ${canCancel?'':'disabled'}>Avboka pass</button>`:!past(s)?'<button class="primary" id="book">Bekräfta bokning</button>':''):''}</div>`);

 if($('#recurring-self'))$('#recurring-self').onclick=()=>recurringForm(id,state.user.id);
 if($('#recurring-book'))$('#recurring-book').onclick=()=>{const uid=admin?Number($('#book-user')?.value):state.user.id;if(uid)recurringForm(id,uid);else modal.querySelector('.error').textContent='Välj en volontär att boka åt.'};
 if($('#book'))$('#book').onclick=()=>bookSlot(id);if($('#cancel'))$('#cancel').onclick=()=>mutate('bookings/'+b.id,'DELETE',null,'Passet är avbokat.');if($('#admin-book'))$('#admin-book').onclick=()=>{const uid=Number($('#book-user').value);if(uid)bookSlot(id,uid);else modal.querySelector('.error').textContent='Ingen bokningsbar volontär vald.'};modal.querySelectorAll('[data-cancel]').forEach(btn=>btn.onclick=()=>mutate('bookings/'+btn.dataset.cancel,'DELETE',null,'Bokningen är borttagen.'));
 if($('#extra-info'))$('#extra-info').onclick=()=>extraInfoForm(id);
 if($('#edit-slot'))$('#edit-slot').onclick=()=>eventForm(id);if($('#cancel-slot'))$('#cancel-slot').onclick=()=>cancelEvent(id);
}
function recurringForm(id,userId=state.user.id){const s=state.slots.find(s=>s.id===id),end=new Date(s.date+'T12:00');end.setDate(end.getDate()+41);const latest=state.slots.filter(x=>x.kind==='regular').map(x=>x.date).sort().pop()||s.date,max=[dateStr(end),latest].sort()[0];show(`<h2>Boka återkommande pass</h2><p>${esc(s.title)} · ${s.start}–${s.end} från ${fmt(s.date)}. ${isAdmin(state.user)?'För: '+esc(state.users.find(u=>u.id===userId)?.name||state.user.name):''}</p><p class="small">Boka samma veckodag och tid till ett valt slutdatum inom det öppna schemat. Serien fortsätter inte automatiskt efter slutdatum. Varje bokning kan sedan avbokas separat enligt vanliga regler.</p><form id="recurring-form"><label>Upprepa<select name="interval"><option value="1">Varje vecka</option><option value="2">Varannan vecka</option><option value="4">Var fjärde vecka</option></select></label><label>Till och med<input type="date" name="until" min="${s.date}" max="${max}" value="${max}" required></label><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Förhandsgranska</button></div></form>`);$('#recurring-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));recurringPreview({slotId:id,userId,interval:Number(data.interval),until:data.until})}}
async function recurringPreview(data){try{const plan=await api('bookings/recurring','POST',{...data,preview:true}),pending=plan.rows.filter(r=>r.status==='new'),labels={new:'Bokas',already:'Redan bokad – behålls',cancelled:'Inställt – hoppas över',missing:'Pass saknas – hoppas över'};show(`<h2>Bekräfta återkommande bokningar</h2><p>${pending.length} nya bokningar. Inställda och saknade pass hoppas över; befintliga bokningar behålls.</p>${plan.rows.map(r=>`<p>${fmt(r.date)} · ${r.start}–${r.end}: <strong>${labels[r.status]}</strong>${r.over_limit?' · Minst 7 anmälda':''}${r.overlap?' · Överlappar en annan bokning':''}</p>`).join('')}<form id="recurring-confirm">${pending.some(r=>r.over_limit)?'<label class="check-label"><input type="checkbox" name="limit" required> Jag vill boka även på pass med minst 7 anmälda.</label>':''}${pending.some(r=>r.overlap)?'<label class="check-label"><input type="checkbox" name="overlap" required> Jag bekräftar bokningarna som överlappar mina andra pass.</label>':''}<p class="error" role="alert"></p><div class="dialog-actions"><button type="button" id="recurring-back">Ändra urval</button><button type="button" data-close>Avbryt</button><button class="primary" ${pending.length?'':'disabled'}>Boka ${pending.length} pass</button></div></form>`);$('#recurring-back').onclick=()=>recurringForm(data.slotId,data.userId);$('#recurring-confirm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('.primary');button.disabled=true;try{state=await api('bookings/recurring','POST',{...data,key:plan.key,confirmOverLimit:Boolean(e.target.elements.limit?.checked),confirmOverlap:Boolean(e.target.elements.overlap?.checked)});modal.close();render();toast('De återkommande passen är bokade.')}catch(err){modal.querySelector('.error').textContent=err.message;button.disabled=false}}}catch(e){const error=modal.querySelector('.error');if(error)error.textContent=e.message;else toast(e.message)}}
function extraInfoForm(id){const s=state.slots.find(s=>s.id===id);show(`<h2>${s.volunteer_meeting?'Information om volontärsträffen':'Extra information på passet'}</h2><p>${esc(s.title)} · ${fmt(s.date)} · ${s.start}–${s.end}</p><form id="extra-info-form"><label>Extra information<textarea name="extra_info" rows="4" maxlength="1000" placeholder="Till exempel: Volontärsträff kl. 18 – välkommen!">${esc(s.extra_info||'')}</textarea></label><p class="small">Visas för volontärerna i schemat och i passets detaljer. Lämna tomt för att ta bort informationen. Bokade deltagare meddelas via den aktiverade e-postkopplingen.</p><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara extra information</button></div></form>`);$('#extra-info-form').onsubmit=e=>{e.preventDefault();mutate('slots/'+id,'PATCH',Object.fromEntries(new FormData(e.target)),'Passinformationen har sparats.')}}
function newSlot(values={}){show(`<h2>Skapa extra pass</h2><p>Skapa ett engångspass eller samma pass återkommande till ett valt slutdatum. Volontärerna bokar sig sedan på respektive pass.</p><form id="slot-form"><input name="kind" type="hidden" value="regular"><label>Namn<input name="title" value="${esc(values.title||'Extra pass')}" required maxlength="100"></label><label>Första datum<input name="date" type="date" value="${values.date||dateStr(new Date())}" required></label><div class="form-grid"><label>Start<input name="start" type="time" value="${values.start||'13:00'}" required></label><label>Slut<input name="end" type="time" value="${values.end||'15:00'}" required></label></div><label>Upprepning<select name="interval" id="slot-repeat">${[[0,'En gång'],[1,'Varje vecka'],[2,'Varannan vecka'],[4,'Var fjärde vecka']].map(([v,label])=>`<option value="${v}" ${Number(values.interval||0)===v?'selected':''}>${label}</option>`).join('')}</select></label><label id="slot-until-label" ${Number(values.interval)?'':'hidden'}>Till och med<input name="until" id="slot-until" type="date" value="${values.until||''}" ${Number(values.interval)?'required':'disabled'}></label><p class="small">Återkommande extra pass kan skapas högst ett år framåt och förhandsgranskas innan de sparas. Redan befintliga pass med samma datum och tid samt inställda söndagspass hoppas över. Varje tillfälle ändras eller ställs in separat.</p><p class="notice">Minst 2 personer behövs, rekommenderat högst 7. Söndagens socialiseringspass är 16–20, även första söndagen i månaden.</p><label>Information<textarea name="note" rows="2" maxlength="1000">${esc(values.note||'')}</textarea></label><label>Extra information (valfritt)<textarea name="extra_info" rows="2" maxlength="1000">${esc(values.extra_info||'')}</textarea></label><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary" id="create-extra-slot">${Number(values.interval)?'Förhandsgranska':'Skapa pass'}</button></div></form>`);$('#slot-repeat').onchange=e=>{const repeat=Number(e.target.value)>0;$('#slot-until-label').hidden=!repeat;$('#slot-until').disabled=!repeat;$('#slot-until').required=repeat;$('#create-extra-slot').textContent=repeat?'Förhandsgranska':'Skapa pass'};$('#slot-form').onsubmit=e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.interval=Number(data.interval);if(data.interval)extraSlotPreview(data);else mutate('slots','POST',data,'Passet har skapats.')}}
async function extraSlotPreview(data){try{const plan=await api('slots/series','POST',{...data,preview:true}),count=plan.rows.filter(r=>r.status==='new').length;show(`<h2>Förhandsgranska extra pass</h2><p>${count} nya pass. Inga volontärer bokas automatiskt.</p><div class="series-preview">${plan.rows.map(r=>`<p>${fmt(r.date)} · ${r.start}–${r.end} · ${esc(r.title)}: <strong>${{new:'Skapas',exists:'Finns redan – hoppas över',cancelled:'Inställt enligt söndagsregeln – hoppas över'}[r.status]}</strong></p>`).join('')}</div><p class="error" role="alert"></p><div class="dialog-actions"><button id="edit-slot-series">Ändra urval</button><button data-close>Avbryt</button><button id="save-slot-series" class="primary" ${count?'':'disabled'}>Skapa ${count} pass</button></div>`);$('#edit-slot-series').onclick=()=>newSlot(data);$('#save-slot-series').onclick=async()=>{const button=$('#save-slot-series');button.disabled=true;try{state=await api('slots/series','POST',{...data,key:plan.key});modal.close();render();toast('De extra passen är skapade.')}catch(e){modal.querySelector('.error').textContent=e.message;button.disabled=false}}}catch(e){modal.querySelector('.error').textContent=e.message}}
function importUsers(){
 show(`<h2>Importera volontärer</h2><p class="small">UTF-8 CSV, högst 500 volontärer. Rubriker: namn;e-post;lösenord och valfritt grön (ja/nej). Lösenord ska ha 10–200 tecken. Befintliga e-postadresser ger ett fel; inga konton importeras då.</p><pre class="small">namn;e-post;lösenord;grön<br>Exempelperson;namn@exempel.se;BytDetta12345;nej</pre><form id="import-form"><label>CSV-fil<input id="import-file" type="file" accept=".csv,text/csv" required></label><label class="check-label"><input id="import-green" type="checkbox"> Grönmarkera alla i importen</label><p class="small">Utan detta val används kolumnen grön. Lämna inloggningsuppgifterna personligen; ingen e-post skickas.</p><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Förhandsgranska</button></div></form>`);
 $('#import-form').onsubmit=async e=>{
  e.preventDefault();const btn=e.target.querySelector('button.primary');btn.disabled=true;
  try{
   const file=$('#import-file').files[0];if(!file||file.size>500000)throw Error('Välj en CSV-fil på högst 500 kB.');
   const payload={csv:await file.text(),green:$('#import-green').checked};
   const preview=await api('users/import-preview','POST',payload);
   show(`<h2>Importera ${preview.users.length} volontärer?</h2><p>${preview.users.filter(u=>u.green).length} grönmarkeras. Alla nya konton blir volontärer.</p><div class="import-preview">${preview.users.map(u=>`<div class="list-row ${u.green?'experienced-volunteer':''}"><span>${esc(u.name)}<br><span class="small">${esc(u.email)}</span></span>${u.green?'Grön':''}</div>`).join('')}</div><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Avbryt</button><button id="confirm-import" class="primary">Importera</button></div>`);
   $('#confirm-import').onclick=async()=>{const confirm=$('#confirm-import');confirm.disabled=true;await mutate('users/import','POST',payload,'Volontärerna har importerats.');if(modal.open)confirm.disabled=false};
  }catch(err){modal.querySelector('.error').textContent=err.message;btn.disabled=false}
 };
}


function upcomingReminders(){
 const now=Date.now(),soon=state.slots.filter(s=>s.mine&&!s.cancelled&&new Date(s.date+'T'+s.start)>now&&new Date(s.date+'T'+s.start)-now<=86400000);
 return soon.length?`<section class="notice reminder-notice" role="status"><strong>Påminnelse: dina pass inom nästa dygn</strong>${soon.map(s=>`<p>${esc(s.title)} · ${fmt(s.date)} kl. ${s.start}–${s.end} <button data-slot="${s.id}">Visa bokning</button></p>`).join('')}</section>`:'';
}
const adminSectionsOpen=new Set(['birthdays','leadership']);
let staffingProblemsOnly=true;
function staffingWeekKey(date){const d=new Date(date+'T12:00');d.setDate(d.getDate()-(d.getDay()+6)%7);return dateStr(d)}
function staffingPage(now=new Date()){const limit=new Date(now);limit.setHours(0,0,0,0);limit.setDate(limit.getDate()+7);const all=state.slots.filter(s=>!s.cancelled&&new Date(s.date+'T'+s.start)>now&&new Date(s.date+'T'+s.start)<limit).sort((a,b)=>(a.date+a.start).localeCompare(b.date+b.start)),problems=all.filter(s=>!staffed(s)||!s.green_booked),shown=staffingProblemsOnly?problems:all;return `<h1>Bemanning</h1><p class="muted">Närmaste 7 dagarna. Minst två personer och gärna minst en grönmarkerad person per pass.</p><div class="panel"><p><strong>${all.filter(s=>!staffed(s)).length}</strong> pass har färre än två bokade · <strong>${all.filter(s=>!s.green_booked).length}</strong> saknar grönmarkerad person.</p><button data-action="staffing-toggle">${staffingProblemsOnly?'Visa alla pass':'Visa endast pass som behöver stöd'}</button></div><section class="panel">${shown.length?shown.map((s,i)=>`${i===0||staffingWeekKey(shown[i-1].date)!==staffingWeekKey(s.date)?`<h2 class="staffing-week-divider">Vecka ${weekNumber(s.date)} · ${fmt(staffingWeekKey(s.date),{day:'numeric',month:'long',year:'numeric'})}</h2>`:''}<div class="list-row"><div><strong>${fmt(s.date,{weekday:'long',day:'numeric',month:'long'})} · ${esc(s.title)}</strong><p>${s.start}–${s.end} · ${esc(staffing(s))}</p><p class="experience-status ${s.green_booked>0?'has-experience':'needs-experience'}">${experienceLabel(s)}</p><p class="small">${state.bookings.filter(b=>b.slot_id===s.id).map(b=>esc(b.name)+(state.users.find(u=>u.id===b.user_id)?.green?' (grön)':'')).join(', ')||'Ingen bokad'}</p></div><button data-slot="${s.id}">Hantera pass</button></div>`).join(''):'<p>Inga pass behöver stöd under perioden.</p>'}</section><p class="small">Grönmarkeringen omfattar rutinerade och manuellt grönmarkerade volontärer samt styrelse och superadmin. Det är ett planeringsstöd och hindrar inte bokning.</p>`}
function birthdayEntries(now=new Date()){const monday=new Date(now);monday.setHours(12,0,0,0);monday.setDate(monday.getDate()-(monday.getDay()+6)%7);const entries=[];for(let day=0;day<7;day++){const date=new Date(monday);date.setDate(date.getDate()+day);for(const m of state.members||[])if(m.status!=='ended'&&m.birth_date?.slice(5)===dateStr(date).slice(5))entries.push({member:m,date:dateStr(date),today:dateStr(date)===dateStr(now)})}return entries}
function birthdayPanel(){const entries=birthdayEntries();return `<details class="admin-section" data-admin-section="birthdays" open><summary>Födelsedagar · ${entries.filter(e=>e.today).length} idag · ${entries.length} denna vecka</summary><div class="admin-section-body"><p>Innevarande vecka, måndag–söndag. Födelsedatum är frivilligt.</p>${entries.length?entries.map(e=>`<p>${e.today?'🎂 <strong>Idag:</strong> ':''}<button class="link" data-member-profile="${e.member.id}">${esc(e.member.name)}</button> · ${fmt(e.date,{weekday:'long',day:'numeric',month:'long'})}</p>`).join(''):'<p>Inga registrerade födelsedagar denna vecka.</p>'}</div></details>`}
function bulletinBoard(){const items=(state.bulletin_board||[]).filter(n=>n.expires_at>Date.now());return `<h1>Anslagstavla</h1><p class="muted">Alla aktuella nyheter från katthemmet. Nyheter som du dolt på startsidan finns kvar här till sluttiden.</p><div class="news-board">${items.length?items.map(n=>`<article class="panel"><h2>${esc(n.title)}</h2><p class="info-text">${esc(n.body)}</p><p class="small">Uppdaterad ${new Date(n.updated_at).toLocaleString('sv-SE')} · Visas till ${new Date(n.expires_at).toLocaleString('sv-SE')}</p></article>`).join(''):'<section class="panel"><p>Det finns inga aktuella nyheter just nu.</p></section>'}</div>`}
function newsBanner(){const items=(state.news||[]).filter(n=>n.expires_at>Date.now());return items.length?`<section class="news-feed" aria-label="Nyheter">${items.map(n=>`<article class="news-banner"><div><span class="eyebrow">NYHET FRÅN KATTHEMMET</span><h2>${esc(n.title)}</h2><p class="info-text">${esc(n.body)}</p>${n.expires_at?`<p class="small">Visas till ${new Date(n.expires_at).toLocaleString('sv-SE')}</p>`:''}</div><button class="news-dismiss" data-dismiss-news="${n.id}" aria-label="Dölj nyheten: ${esc(n.title)}">Dölj</button></article>`).join('')}</section>`:''}
async function dismissNews(id,button){const item=state.news.find(n=>n.id===id);button.disabled=true;try{state=await api('news/'+id+'/dismiss','POST',{revision:item.revision});render()}catch(e){toast(e.message);button.disabled=false}}
function newsAdminPanel(){const items=state.news_admin||[];return `<details class="admin-section" data-admin-section="news"><summary>Nyheter och anslagstavla</summary><div class="admin-section-body"><p>Publicera uppdateringar och annan information med obligatorisk sluttid. Läsaren kan dölja nyheten på startsidan men den ligger kvar på Anslagstavla till sluttiden. En ändrad nyhet visas igen på startsidan.</p><button class="primary" data-action="new-news">+ Skapa nyhet</button>${items.map(n=>`<div class="list-row"><div><strong>${esc(n.title)}</strong><p class="small">${!n.published?n.expires_at===null?'Utkast – välj visningstid':'Avpublicerad':n.expires_at&&n.expires_at<=Date.now()?'Visningstiden har gått ut':n.expires_at?'Publicerad till '+new Date(n.expires_at).toLocaleString('sv-SE'):'Välj sluttid före publicering'}</p></div><div class="actions"><button data-edit-news="${n.id}">Redigera</button><button data-delete-news="${n.id}">Radera</button>${n.published?`<button data-unpublish-news="${n.id}">Avpublicera</button>`:''}</div></div>`).join('')}</div></details>`}
function deleteNews(id){const n=state.news_admin.find(item=>item.id===id);if(!n)return;show(`<h2>Radera nyhet?</h2><p>Nyheten ”${esc(n.title)}” tas bort permanent från startsidan, anslagstavlan och administrationen.</p><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Avbryt</button><button id="confirm-delete-news" class="primary">Radera nyheten</button></div>`);$('#confirm-delete-news').onclick=async e=>{e.target.disabled=true;await mutate('news/'+id,'DELETE',{revision:n.revision},'Nyheten har raderats.');if(modal.open)e.target.disabled=false}}
function newsForm(id){const n=id?state.news_admin.find(n=>n.id===id):{title:'',body:'',expires_at:null,published:true},localInput=value=>{if(!value)return '';const d=new Date(value);return dateStr(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')};show(`<h2>${id?'Redigera nyhet':'Skapa nyhet'}</h2><form id="news-form"><label>Rubrik<input name="title" maxlength="150" value="${esc(n.title)}" required></label><label>Text<textarea name="body" rows="5" maxlength="4000" required>${esc(n.body)}</textarea></label><label>Visningstid – välj ett alternativ<select id="news-duration" required><option value="" disabled ${!n.expires_at?'selected':''}>Välj visningstid…</option><option value="1">1 dag</option><option value="3">3 dagar</option><option value="7">7 dagar</option><option value="14">14 dagar</option><option value="30">30 dagar</option><option value="custom" ${n.expires_at?'selected':''}>Välj slutdatum och tid</option></select></label><label id="news-expiry-label" ${n.expires_at?'':'hidden'}>Slutar visas<input id="news-expiry" name="expires" type="datetime-local" value="${localInput(n.expires_at)}" ${n.expires_at?'required':'disabled'}></label><label class="check-label"><input name="published" type="checkbox" ${n.published?'checked':''}> Publicera på startsidan och anslagstavlan</label><p class="small">En sluttid måste väljas före publicering. Läsaren kan dölja nyheten på startsidan, men inte på anslagstavlan. På anslagstavlan ligger den kvar till sluttiden. När nyheten redigeras visas den nya versionen igen på startsidan.</p><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">${id?'Spara':'Publicera nyhet'}</button></div></form>`);$('#news-duration').onchange=e=>{const input=$('#news-expiry');$('#news-expiry-label').hidden=false;input.disabled=false;input.required=true;if(['1','3','7','14','30'].includes(e.target.value)){const d=new Date();d.setDate(d.getDate()+Number(e.target.value));input.value=localInput(d)}else input.value=''};$('#news-form').onsubmit=async e=>{e.preventDefault();const fields=e.target.elements,expires=fields.expires.disabled||!fields.expires.value?null:new Date(fields.expires.value).getTime();if(fields.published.checked&&(!$('#news-duration').value||!Number.isSafeInteger(expires)||expires<=Date.now())){modal.querySelector('.error').textContent='Välj en visningstid och sluttid i framtiden.';return}const button=e.target.querySelector('.primary');button.disabled=true;await mutate(id?'news/'+id:'news',id?'PUT':'POST',{title:fields.title.value,body:fields.body.value,expires_at:expires,published:fields.published.checked,...(id?{revision:n.revision}:{})},'Nyheten har sparats.');if(modal.open)button.disabled=false}}
function adminWarnings(){
 const inactive=state.users.filter(u=>u.inactive_month),mail=state.email_reminders;
 return `<details class="admin-section" data-admin-section="followup"><summary>Volontärer att följa upp</summary><div class="admin-section-body">${inactive.length?inactive.map(u=>`<p><strong>${esc(u.name)}</strong> · ${esc(u.email)} · ${u.last_completed_at?'Senaste genomförda pass: '+new Date(u.last_completed_at).toLocaleDateString('sv-SE'):'Inget genomfört pass sedan registrering för minst 60 dagar sedan'}</p>`).join(''):'<p>Ingen aktiv volontär har varit borta 60 dagar.</p>'}<p class="small">Beräknat från avslutade bokningar, inte bekräftad närvaro. Nya volontärer får 60 dagars starttid.</p></div></details><details class="admin-section" data-admin-section="email"><summary>E-post och påminnelser</summary><div class="admin-section-body"><p>${state.change_notifications?.pending||0} ändringsmejl väntar på utskick${state.change_notifications?.failed?' · '+state.change_notifications.failed+' misslyckade, nytt försök görs automatiskt':''}. Ändringar och inställda pass meddelas till bokade deltagare.</p><p>Påminnelser på sidan visas för egna pass inom nästa dygn.</p><p>${mail?.configured?'E-post aktiverad via '+(mail.provider==='gmail'?'Gmail':'Resend')+': automatiskt inom 24 timmar före passet. '+mail.sent_count+' påminnelser skickade.':'E-post är inte aktiverad. En superadmin kan koppla ett Gmail-konto via E-postinställningar.'}</p>${mail?.last_error?`<p class="error">${esc(mail.last_error)}</p>`:''}${isSuperAdmin(state.user)?'<button id="email-settings">E-postinställningar</button>':''} <button id="send-reminders" ${mail?.configured?'':'disabled'}>Skicka påminnelser för nästa dygn</button></div></details>`;
}
function changeRole(id,role){const u=state.users.find(u=>u.id===id);show(`<h2>Ändra roll för ${esc(u.name)}?</h2><p>${role==='superadmin'?'Superadmin får hantera administratörskonton, behörigheter och systeminställningar.':role==='admin'?'Styrelsen får hantera den löpande verksamheten och volontärprofilerna.':'Kontot får volontärbehörighet.'}</p><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Avbryt</button><button class="primary" id="confirm-role">Bekräfta</button></div>`);$('#confirm-role').onclick=()=>mutate('users/'+id,'PATCH',{role},'Rollen har uppdaterats.')}
async function bookSlot(id,userId,confirmOverLimit=false,confirmOverlap=false){
 try{state=await api('bookings','POST',{slotId:id,...(userId?{userId}:{}),confirmOverLimit,confirmOverlap});modal.close();render();toast('Bokningen är klar. Tack för din tid!')}
 catch(e){if(e.code==='RECOMMENDED_LIMIT'){
  show(`<h2>Redan minst 7 anmälda</h2><p>Det rekommenderade taket är 7 personer per pass. Är du säker på att du vill boka ytterligare en person?</p><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Avbryt</button><button class="primary" id="confirm-over-limit">Ja, boka ändå</button></div>`);
  $('#confirm-over-limit').onclick=()=>bookSlot(id,userId,true,confirmOverlap);
 }else if(e.code==='OVERLAPPING_BOOKING'){confirmOverlapDialog(e.message,()=>bookSlot(id,userId,confirmOverLimit,true))}else{const error=modal.open?modal.querySelector('.error'):null;if(error)error.textContent=e.message;else toast(e.message)}}
}


function eventList(){const events=state.slots.filter(s=>s.kind==='event'&&new Date(s.date+'T'+s.end)>new Date());return `<details class="admin-section" data-admin-section="events"><summary>Händelser</summary><div class="admin-section-body"><p class="small">Lägg in till exempel veterinärbesök. Ändra datum och tid med Boka om; befintliga deltagare följer med.</p>${events.length?events.map(s=>`<div class="list-row"><div><strong>${esc(s.title)}</strong><p class="small">${fmt(s.date)} · ${s.start}–${s.end} · ${s.cancelled?'Inställd':s.booked+' anmälda'}</p></div><div class="actions"><button data-slot="${s.id}">Visa deltagare</button><button data-edit-event="${s.id}">${s.cancelled?'Boka om':'Ändra / boka om'}</button></div></div>`).join(''):'<p class="small">Inga kommande händelser.</p>'}</div></details>`}
function eventForm(id){
 const s=id?state.slots.find(s=>s.id===id):null;
 show(`<h2>${s?'Ändra / boka om '+(s.kind==='event'?'händelse':'pass'):'Skapa händelse'}</h2><form id="event-form"><input name="kind" type="hidden" value="event"><label>Namn<input name="title" required maxlength="100" value="${esc(s?.title||'Veterinärbesök')}"></label><label>Datum<input name="date" type="date" value="${s?.date||dateStr(new Date())}" required></label><div class="form-grid"><label>Start<input name="start" type="time" value="${s?.start||'13:00'}" required></label><label>Slut<input name="end" type="time" value="${s?.end||'14:00'}" required></label></div><label>Information<textarea name="note" maxlength="1000" rows="3">${esc(s?.note||'')}</textarea></label><label>Extra information (valfritt)<textarea name="extra_info" rows="2" maxlength="1000" placeholder="Till exempel: Volontärsträff kl. 18 – välkommen!">${esc(s?.extra_info||'')}</textarea></label><p class="notice">${s?'Deltagarnas bokningar behålls. Vid överlappande tider behöver du bekräfta ändringen. Berörda deltagare meddelas via e-post när e-post är aktiverad. Ett inställt pass blir bokningsbart igen när du sparar.':'Händelsen visas i schemat och volontärer kan boka sig. Minst 2, rekommenderat högst 7 deltagare.'}</p><p class="error" role="alert"></p><div class="dialog-actions">${s&&!s.cancelled?'<button type="button" id="cancel-event">Ställ in</button>':''}<button type="button" data-close>Avbryt</button><button class="primary">${s?'Spara ändring':'Skapa händelse'}</button></div></form>`);
 $('#event-form').onsubmit=e=>{e.preventDefault();mutate(s?'slots/'+s.id:'slots',s?'PATCH':'POST',Object.fromEntries(new FormData(e.target)),s?'Ändringen har sparats.':'Händelsen har skapats.')};
 if($('#cancel-event'))$('#cancel-event').onclick=()=>cancelEvent(id);
}
function cancelEvent(id){const s=state.slots.find(s=>s.id===id);show(`<h2>Ställa in ${s.kind==='event'?'händelsen':'passet'}?</h2><p>${esc(s.title)} den ${fmt(s.date)} kl. ${s.start}–${s.end}.</p><p>${s.booked} anmälningar behålls i historiken. Passet spärras för nya bokningar och räknas inte som genomfört. Deltagarna meddelas via e-post när e-post är aktiverad.</p><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Behåll ${s.kind==='event'?'händelsen':'passet'}</button><button class="danger" id="confirm-cancel-event">Ställ in</button></div>`);$('#confirm-cancel-event').onclick=()=>mutate('slots/'+id,'PATCH',{cancelled:true},'Passet är inställt.')}


async function emailSettingsDialog(message=''){
 try{
  const settings=await api('email-settings');
  show(`<h2>E-postinställningar – Gmail</h2><p class="small">Aktivera tvåstegsverifiering i Google-kontot och skapa ett applösenord. Använd applösenordet här. <a href="https://support.google.com/mail/answer/185833?hl=sv" target="_blank" rel="noopener noreferrer">Googles instruktioner</a></p><form id="email-settings-form"><label>Gmail-adress<input name="gmail_address" type="email" required maxlength="254" autocomplete="off" value="${esc(settings.gmail_address)}"></label><label>Gmail-applösenord<input name="app_password" type="password" autocomplete="new-password" maxlength="30" ${settings.password_saved?'':'required'} placeholder="${settings.password_saved?'Sparat – lämna tomt för att behålla':'16 tecken från Google'}"></label><p class="small">${settings.password_saved?'Ett applösenord finns sparat. Det visas aldrig igen.':'Applösenordet lagras krypterat på servern.'}</p><label>Sidans webbadress<input name="app_url" type="url" required value="${esc(settings.app_url)}" placeholder="https://katthem.exempel.se"></label><p class="small">Länken som volontärerna ska öppna från påminnelsen. Använd er publika HTTPS-adress vid gemensam drift.</p><label class="check-label"><input name="enabled" type="checkbox" ${settings.enabled?'checked':''}> Aktivera Gmail för påminnelser, ändringsmejl och lösenordsåterställning</label><fieldset><legend>CSV-export via e-post</legend><p class="small">CSV-filer skickas till samma Gmail-adress som ovan. De innehåller volontärprofiler, kontouppgifter, schema, bokningar, praktisk information, introduktionskryss, engagemang, rutinversioner och anonyma bemanningstal. Lösenord, dörrkod och privata kalenderlänkar ingår inte.</p><label class="check-label"><input name="csv_enabled" type="checkbox" ${settings.csv_enabled?'checked':''}> Aktivera automatiska CSV-utskick</label><label>Intervall<select name="csv_interval">${[['daily','Dagligen'],['weekly','Varje vecka'],['monthly','Varje månad']].map(([value,label])=>`<option value="${value}" ${(settings.csv_interval||'weekly')===value?'selected':''}>${label}</option>`).join('')}</select></label><p class="small">Första utskicket sker efter ett valt intervall från att inställningen sparas: 24 timmar, 7 dagar eller en kalendermånad. Servern behöver vara igång. Efter ett lyckat utskick räknas nästa intervall därifrån. Byte av intervall eller Gmail-adress startar om schemat.</p><p class="small">Senast skickat: ${settings.csv_export_status?.last_sent?new Date(settings.csv_export_status.last_sent).toLocaleString('sv-SE'):'Inte skickat ännu'}<br>Nästa utskick: ${settings.csv_export_status?.next_at?new Date(settings.csv_export_status.next_at).toLocaleString('sv-SE'):'Inte schemalagt'}</p>${settings.csv_export_status?.last_error?`<p class="error">${esc(settings.csv_export_status.last_error)}</p>`:''}<button type="button" id="send-csv-now" ${settings.password_saved&&settings.enabled?'':'disabled'}>Skicka CSV nu</button><p class="small">Knappen skickar till den sparade Gmail-adressen. Spara ändringar först. Ett manuellt utskick flyttar nästa schemalagda utskick framåt.</p></fieldset><p class="small">Spara först och skicka ett testmejl. När Gmail sparas ersätter dessa inställningar eventuell Resend-koppling. Avmarkera för att stänga av e-post.</p><p class="error" role="alert"></p><p class="small" id="email-status" role="status">${esc(message)}</p><div class="dialog-actions"><button type="button" data-close>Stäng</button><button class="primary">Spara inställningar</button></div></form><hr><form id="email-test-form"><h3>Skicka testmejl</h3><label>Mottagaradress<input name="to" type="email" required value="${esc(state.user.email.endsWith('.local')?'':state.user.email)}" placeholder="din-adress@gmail.com"></label><p class="small">Testet använder sparade Gmail-inställningar och fungerar även innan automatiska påminnelser aktiverats.</p><button ${settings.password_saved?'':'disabled'}>Skicka testmejl</button></form>`);
  $('#email-settings-form').onsubmit=async e=>{
   e.preventDefault();const form=e.target,button=form.querySelector('button.primary');button.disabled=true;
   try{const values=Object.fromEntries(new FormData(form));await api('email-settings','PUT',{gmail_address:values.gmail_address,app_password:values.app_password,app_url:values.app_url,enabled:form.elements.enabled.checked,csv_interval:values.csv_interval,csv_enabled:form.elements.csv_enabled.checked});form.elements.app_password.value='';state=await api('state');render();await emailSettingsDialog('Inställningarna är sparade. Skicka gärna ett testmejl.')}catch(err){modal.querySelector('.error').textContent=err.message;button.disabled=false}
  };
  $('#send-csv-now').onclick=async()=>{const button=$('#send-csv-now');button.disabled=true;try{await api('email-settings/csv-send','POST',{});await emailSettingsDialog('CSV-exporten har skickats till den sparade Gmail-adressen.')}catch(e){modal.querySelector('.error').textContent=e.message;button.disabled=false}};
  $('#email-test-form').onsubmit=async e=>{
   e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;modal.querySelector('.error').textContent='';$('#email-status').textContent='Skickar testmejl…';
   try{await api('email-settings/test','POST',Object.fromEntries(new FormData(e.target)));$('#email-status').textContent='Testmejlet har skickats. Kontrollera inkorgen och skräpposten.'}catch(err){$('#email-status').textContent='';modal.querySelector('.error').textContent=err.message}finally{button.disabled=false}
  };
 }catch(err){toast(err.message)}
}


function resetUserPassword(id){
 const u=state.users.find(u=>u.id===id);
 show(`<h2>Byt lösenord för ${esc(u.name)}</h2><p class="small">${esc(u.email)}</p><form id="reset-user-password"><label>Nytt lösenord<input name="password" type="password" minlength="10" maxlength="200" autocomplete="new-password" required></label><label>Bekräfta nytt lösenord<input name="confirm" type="password" minlength="10" maxlength="200" autocomplete="new-password" required></label><p class="notice">Alla inloggningar för kontot avslutas. Lämna det nya lösenordet till personen direkt. Inget mejl skickas. Personen kan sedan byta lösenord under Mitt konto.</p><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara nytt lösenord</button></div></form>`);
 $('#reset-user-password').onsubmit=async e=>{
  e.preventDefault();const values=Object.fromEntries(new FormData(e.target));
  if(values.password!==values.confirm){modal.querySelector('.error').textContent='Lösenorden stämmer inte överens.';return}
  const button=e.target.querySelector('button.primary');button.disabled=true;
  await mutate('users/'+id+'/password','POST',{password:values.password},'Lösenordet har ändrats och kontots inloggningar har avslutats.');
  if(modal.open)button.disabled=false;else modal.innerHTML='';
 };
}

const infoFields=[['location','Adress och hitta hit']];
function volunteerInfo(){const info=state.volunteer_info||{};return `<h1>Praktisk information</h1><p class="muted">Praktisk information inför ditt pass.</p>${isAdmin(state.user)?'<button id="edit-info">Redigera information</button>':''}${infoFields.map(([key,title])=>`<section class="panel"><h2>${title}</h2><p class="info-text">${info[key]?esc(info[key]):state.shelter?.configured===false?'Ingen adress är kopplad till din angivna ort. Kontakta admin.':'Information kommer. Administratören fyller i uppgifterna här.'}</p></section>`).join('')}<section class="panel"><h2>Volontärsträffar</h2><p>Efter öppet hus första söndagen i månaden är det volontärsträff kl. 15–16. Öppna träffen i schemat för aktuell information och bokning. Admin och superadmin kan redigera informationen och vid behov ändra eller ställa in träffen.</p></section><section class="panel"><h2>Överlämning mellan pass</h2><p>Överlämning sker på plats på katthemmet. Läs whiteboardtavlan när du kommer och skriv viktig information till nästa pass där. Mediciner hanteras enligt papperslistan på katthemmet. Vid sena förhinder kontaktar du katthemmets bemanningsgrupp i Messenger.</p></section>${routinePanel()}${contactDirectory()}${volunteerChecklist()}${portalManual()}`}
function messengerContact(person){if(person.messenger_url){try{const u=new URL(person.messenger_url);if(u.protocol==='https:'&&!u.username&&!u.password&&!u.port&&(['m.me','messenger.com','www.messenger.com'].includes(u.hostname)&&u.pathname!=='/'||['facebook.com','www.facebook.com','m.facebook.com'].includes(u.hostname)&&u.pathname.startsWith('/messages/t/')))return `<a href="${esc(u.href)}" target="_blank" rel="noopener noreferrer">Kontakta via Messenger</a>`}catch{}}return 'Kontakta via Messenger'}
function contactDirectory(){const people=state.contacts||[];return `<section class="panel"><h2>Kontaktpersoner – styrelsen och djurvårdsutbildade</h2><p class="small">Kontaktuppgifter för inloggade volontärer. Saknas telefonnummer kontaktar du personen via Messenger.</p>${people.length?people.map(p=>`<div class="list-row"><div><strong>${esc(p.name)}</strong><p>${[p.board_role!=='none'?boardRoleLabel(p):'',p.animal_care_trained?'Djurvårdsutbildad':'',p.responsibilities].filter(Boolean).map(esc).join(' · ')}</p>${p.shelter?`<p class="small">Katthem: ${esc(p.shelter)}</p>`:''}<p>${p.phone?esc(p.phone):messengerContact(p)}${p.phone&&p.messenger_url?' · '+messengerContact(p):''}</p></div></div>`).join(''):'<p>Inga kontaktpersoner är markerade ännu. Admin och superadmin fyller i styrelseuppdrag och utbildning i volontärprofilerna.</p>'}</section>`}
function registrationGuide(){if(!isAdmin(state.user))return '';return `<details class="registration-guide"><summary>Samla in uppgifter – formulär och Excel</summary><div class="registration-guide-content"><p>Samla bara in uppgifter för volontärarbete och kontakt. Medlemsregister ingår inte i volontärmodulen.</p><h3>Volontärer – färdig CSV-import</h3><p>Använd en rad per volontär med rubrikerna:</p><p class="info-text"><code>namn;e-post;lösenord;grön</code></p><p>Formuläret samlar namn och e-post. Admin tilldelar ett unikt startlösenord med 10–200 tecken och lämnar det personligen; samla inte in personens befintliga lösenord. Grön är valfritt ja/nej och börjar gälla först efter klar checklista.</p><p>Spara som CSV UTF-8 med semikolon eller komma. Administration → Importera och exportera CSV → Importera från CSV. Förhandsgranska före import. Högst 500 personer; befintliga konton uppdateras inte.</p><h3>Kompletta volontäruppgifter – insamlingsunderlag</h3><p class="info-text"><code>Namn;E-post;Telefon;Messenger-länk;Katthem;Djurvårdsutbildning;Födelsedatum;Volontärstatus;Styrelseroll;Annan styrelseroll;Ytterligare ansvar;Övrig information</code></p><p>CSV-importen tar bara emot namn, e-post, startlösenord och grönmarkering. Övriga uppgifter kompletteras i samma profil via Volontärer → Visa volontärprofil → Redigera profil. För en ny person används Lägg till volontär. Katthem bestäms av den valda verksamheten och tilldelad åtkomst. Födelsedatum är frivilligt och används för födelsedagshälsningar. Utbildning anges som ja/nej. Uppdrag och ytterligare ansvar beskriver arbetet i katthemmet.</p><p>Medlemsmarkering, medlemsnummer, medlemsdatum och hemadress samlas inte in, visas inte och ingår inte i volontärexporter. Ett framtida medlemsregister kan erbjudas som separat, valbar modul med egna ändamål och behörigheter.</p></div></details>`}
const checklistSaving=new Set();
function volunteerChecklist(){const checklist=state.checklist;if(isAdmin(state.user)||!checklist)return '';const checked=new Set(checklist.checked_items),total=checklist.groups.reduce((n,g)=>n+g.items.length,0);return `<section class="panel onboarding-checklist"><h2>Min första tid på katthemmet</h2><p>Gå igenom checklistan tillsammans med en erfaren volontär. Kryssa i det du har gått igenom; du kan ta bort ett kryss om du vill återkomma till punkten. Arbetsinstruktionerna finns analogt på katthemmet.</p><p class="small"><strong id="checklist-count">${checked.size} av ${total} punkter klara</strong> · <span id="checklist-status" role="status" aria-live="polite">Dina personliga kryss sparas automatiskt. Alla punkter krävs för grönmarkering.</span></p>${checklist.groups.map(group=>`<fieldset><legend>${esc(group.title)}</legend>${group.items.map(item=>`<label class="check-label checklist-item"><input type="checkbox" data-checklist-item="${esc(item.id)}" ${checked.has(item.id)?'checked':''}><span>${esc(item.text)}</span></label>`).join('')}</fieldset>`).join('')}</section>`}
async function saveChecklistItem(input){const id=input.dataset.checklistItem,checked=input.checked,userId=state.user.id;checklistSaving.add(id);input.disabled=true;if($('#checklist-status'))$('#checklist-status').textContent='Sparar…';try{await api('checklist','PATCH',{item_id:id,checked});if(state?.user.id!==userId)return;const items=new Set(state.checklist.checked_items);if(checked)items.add(id);else items.delete(id);state.checklist.checked_items=[...items];const fresh=await api('state');if(state?.user.id===userId){state=fresh;render()}const total=state.checklist.groups.reduce((n,g)=>n+g.items.length,0);if($('#checklist-count'))$('#checklist-count').textContent=`${items.size} av ${total} punkter klara`;if($('#checklist-status'))$('#checklist-status').textContent='Dina kryss är sparade.'}catch(err){input.checked=!checked;if($('#checklist-status'))$('#checklist-status').textContent='Kunde inte spara. Försök igen.';toast(err.message)}finally{checklistSaving.delete(id);input.disabled=false;if(checklistSaving.size&&$('#checklist-status'))$('#checklist-status').textContent='Sparar…'}}
function portalManual(){
 const admin=isAdmin(state.user),superadmin=isSuperAdmin(state.user);
 const chapters=[
 ['Min profil',['Mitt konto → Min profil: uppdatera dina egna kontaktuppgifter, telefon, Messenger-länk och frivilligt födelsedatum. Namn och inloggningsadress ändras i ditt ordinarie katthem; växla dit först om fälten är låsta. Ändringar av inloggningsadressen gäller nästa inloggning.','Behörighet, katthemsåtkomst, uppdrag, utbildningsmarkering, introduktionsgodkännande och grönmarkering hanteras av admin. Övriga volontärer ser endast de kontaktuppgifter som hör till ett publicerat uppdrag i kontaktlistorna.']],
 ['Engagemang, introduktion och gallring',[
 'Mitt konto → Mitt engagemang: pausa med ett uppföljningsdatum eller avsluta. Välj det aktuella katthemmet eller hela föreningen. Avboka kommande pass först; vid sena förhinder kontaktas bemanningsgruppen i Messenger.',
 'Paus och inaktivitet raderar ingenting automatiskt. Efter 60 dagars frånvaro visas en signal för admin att ta kontakt. Status ändras aldrig automatiskt på grund av frånvaro.',
 'Ett uttryckligt avslut startar en frist på tre kalendermånader. Admin får en varning efter två månader och två veckor. Därefter gallras profilen, identifierbara bokningar, checklistan och kalenderlänkar automatiskt. Anonyma bemanningstal bevaras. Detta är föreningens valda gallringsregel, inte en allmän lagstadgad tidsfrist.',
 'Ett dokumenterat annat ändamål kan motivera ett gallringsundantag med datum för ny prövning. Konton med administratörsuppdrag gallras inte innan behörigheterna har hanterats. Admin granskar detta under Administration → Engagemang, introduktion och gallring.',
 'Ett avslut på ett katthem påverkar inte fortsatt arbete i ett annat. Den gemensamma inloggningen sparas så länge den behövs för kvarvarande engagemang. Ett gallrat hem försvinner från åtkomsten. Historiska säkerhetskopior och tidigare exporter måste hanteras separat enligt föreningens lagringspolicy.',
 'Efter gallring registreras återvändande volontärer på nytt och genomför ny introduktion. Återaktivering efter avslut före gallring och flytt till ett annat hem kräver också ny lokal introduktion. Gallrade personuppgifter kan inte återskapas i appen.',
 'Praktisk information → Aktuella rutiner: läs och bekräfta den aktuella versionen. Version och tidpunkt sparas. Admin publicerar nya versioner per katthem. En ny version behöver bekräftas före nästa självständiga bokning.',
 'Nya volontärer genomför checklistan och praktisk introduktion; admin godkänner sedan självständig bokning. Admin kan boka handledda introduktionspass åt en aktiv volontär. Befintliga konton behåller sin tidigare introduktionsbehörighet när funktionen införs. Grönmarkering är separat och kräver fortfarande checklista samt tio pass eller manuell grönmarkering.'
 ]],
 ['Nyheter ovanför kalendern',[
  'Publicerade nyheter visas ovanför kalendern och på fliken Anslagstavla för alla inloggade volontärer. De kan handla om uppdateringar, träffar eller annan information.',
  'Dölj tar bort nyheten för ditt konto, även efter utloggning och på andra enheter. Nyheten finns ändå kvar på Anslagstavla till sluttiden och andra personer ser den fortfarande på startsidan. När texten redigeras visas den uppdaterade versionen igen på startsidan.',
  'Alla publicerade nyheter måste ha en sluttid. På Anslagstavla finns ingen Dölj-knapp; där försvinner nyheten när sluttiden passerar. Admin och superadmin kan också avpublicera eller radera den.'
 ]],
 ['Hitta rätt i schemat',[
  'Måndag–lördag är ordinarie pass 08–12, 16–18 och 18–20. Söndagar är det morgonpass 08–12 och socialiseringspass 16–20. Söndagar 16–20 träffas socialiseringsgruppen och utför ordinarie uppgifter samt socialiseringsträning med katterna.',
  'Första söndagen i månaden är det öppet hus 11–15, följt av volontärsträff 15–16. Socialiseringsgruppen arbetar 16–20 även den dagen. Öppna träffen för aktuell information; en träff kan ha ändrats eller ställts in.',
  'Byt vecka med pilarna och använd Idag för att återgå till aktuell vecka. Filtrera med Alla pass, Behöver fler eller Mina pass.',
  'Ordinarie schema fylls på automatiskt 42 dagar framåt. Uppdatera nu hämtar det senaste läget. När fliken är synlig uppdateras schemat ungefär var 30:e sekund; öppna dialoger skyddas från automatisk omladdning.'
 ]],
 ['Färgerna på passen och grönmarkering',[
  'Minst två personer behövs per pass. Rött betyder att färre än två är bokade på ett framtida pass inom sju dagar. Texten på passkortet visar hur många som saknas.',
  'Morgonpass har grön kant och eftermiddags-/kvällspass orange kant. Röd bemanningsmarkering går före tidsfärgerna. Ljusgrön bakgrund betyder att du själv är bokad; läs även texten Du är bokad.',
  'Saknar grönmarkerad person betyder att ingen grönmarkerad är bokad. Det är ett planeringsstöd som inte hindrar bokning. Markeringen ändras när någon grönmarkerad bokar sig.',
  'Volontärer blir gröna vid minst 10 genomförda bokade pass och helt genomförd introduktionschecklista. Manuell grönmarkering kan ersätta passkravet, men checklistan måste alltid vara klar även efter CSV-import. Admin och superadmin räknas alltid som gröna.'
 ]],
 ['Boka ett pass',admin?[
  'För egen bokning kan du klicka på Bekräfta bokning direkt under Hantera pass på passkortet. Knappen visas när du inte redan är bokad och passet inte har börjat eller är inställt.',
  'Du kan också öppna Hantera pass och välja Bekräfta bokning längst ned, samma knapp som volontärerna använder. Egen bokning använder ditt inloggade konto även om en annan volontär är vald i listan.',
  'För att boka åt någon annan öppnar du passet, väljer personen under Boka åt volontär och klickar på Boka vald volontär.',
  'Rekommenderat högst sju personer gäller alla pass. Från den åttonde deltagaren krävs extra bekräftelse. Överlappande tider kräver också bekräftelse; kontrollera att personen kan delta i båda passen.'
 ]:[
  'Öppna ett framtida aktivt pass med Boka pass och läs passinformationen, dagens städning och eventuell extra information.',
  'Klicka på Bekräfta bokning. Du ser därefter Du är bokad i schemat och passet under Mina bokningar.',
  'Rekommenderat högst sju personer gäller alla pass. Om minst sju redan är anmälda får du bekräfta en extra gång. Det finns ingen absolut bokningsspärr vid sju.',
  'Om tiderna överlappar en annan bokning visas en fråga. Bekräfta bara om du kan delta i båda passen, exempelvis morgonpass och öppet hus.'
 ]],
 ['Boka återkommande pass',[
  'Öppna ett framtida ordinarie pass och välj Boka återkommande. Välj varje, varannan eller var fjärde vecka och ett slutdatum inom det öppna schemat, högst sex veckor efter startpasset.',
  'Förhandsgranska visar vilka datum som bokas. Redan bokade pass behålls; inställda och saknade pass hoppas över. Bekräfta eventuella överlappningar och pass med minst sju anmälda innan du bokar serien.',
  'Serien fortsätter inte automatiskt efter slutdatumet. Varje bokning kan avbokas separat enligt vanliga avbokningsregler. Om schemat ändras mellan förhandsgranskning och bokning behöver urvalet förhandsgranskas igen.',
  ...(admin?['För egen återkommande bokning använder du Boka återkommande i passets knapprad. Boka återkommande åt vald volontär gäller i stället personen som valts i listan.']:[])
 ]],
 ['Mina bokningar och antal genomförda pass',[
  'Mina bokningar visar dina kommande pass. Visa bokning öppnar detaljerna. Kommande inställda pass som du varit bokad på visas under Inställda pass.',
  'Mina bokningar och Mitt konto visar ditt antal genomförda pass. Bokningar räknas efter passets sluttid; inställda pass räknas inte. Efter en flytt räknas också medförda genomförda pass från tidigare katthem. Detta bygger på bokningar, inte på registrerad närvaro.'
 ]],
 ['Avboka vid förhinder',[
  'Öppna ditt pass och välj Avboka pass. Kontrollera därefter att passet inte finns kvar bland dina kommande bokningar.',
  'Volontärer kan själva avboka fram till 24 timmar före starten. Vid senare förhinder, kontakta katthemmets bemanningsgrupp i Messenger. Ersättare ordnas manuellt i Messenger.',
  ...(admin?['Admin och superadmin kan hjälpa till med sena avbokningar. Under Bokade volontärer väljer du Avboka vid rätt person. Detta tar bara bort den bokningen; Ställ in gäller hela passet.']:[])
 ]],
 ['Spara kalenderfiler för ett pass eller en vecka',[
  'Lägg till i kalender på din bokning hämtar en .ics-fil för passet. Ladda ner mina pass denna vecka i veckovyn hämtar alla dina ej inställda bokningar för den visade veckan i samma fil.',
  'Kalenderposterna heter Katthemmet – passets namn och innehåller adressen för ditt kopplade katthem, passets information och dagens arbetsuppgifter. Tiderna använder Europe/Stockholm.',
  'En importerad fil är en engångskopia och uppdateras inte vid nya bokningar, ombokningar eller avbokningar. För automatiska uppdateringar använder du i stället kalenderprenumeration.',
  'Posterna innehåller en påminnelse 12 timmar före passet. Kalenderappen avgör hur den hanteras. Restid och avresepåminnelse ställer du in i din egen kalenderapp med adressen som plats.'
 ]],
 ['Prenumerera på mina pass',[
  'Välj Prenumerera på mina pass i veckovyn eller under Mina bokningar. Kopiera din privata länk och lägg till den som en kalenderprenumeration via webbadress, inte som en nedladdad fil.',
  'Google Kalender: välj Andra kalendrar, plusknappen och Från webbadress. I Apple Kalender och Outlook väljer du en kalenderprenumeration från webbadress.',
  'Kalenderappen hämtar nya och ändrade bokningar samt avbokningar med sitt eget intervall. Detta är ingen omedelbar push. Kontrollera alltid portalen vid sena ändringar.',
  'På Mac kan du välja Visa info på prenumerationskalendern och kontrollera Autouppdatera. Innehåll → Uppdatera kalendrar startar en manuell uppdatering. På iPhone finns hämtningsschemat under Inställningar → Appar → Kalender → Kalenderkonton → Hämta nya data. Automatiskt kan vänta tills telefonen laddas och använder Wi-Fi.',
  'Länken ger tillgång till dina pass utan inloggning och ska inte delas med andra. Återkalla länken stoppar framtida hämtning via den gamla länken. Skapa och lägg till en ny länk om du vill börja prenumerera igen; gamla kalenderkopior kan finnas kvar.',
  'För en extern kalender använder du länken från den publicerade sidan. En länk med 127.0.0.1 är lokal och fungerar inte för externa kalendertjänster.'
 ]],
 ['Passinformation, städning och överlämning',[
  'Dagens städning visas när du öppnar passet, inte i kalenderns passkort. Läs också Extra information för det aktuella passet.',
  'Måndag: storstäda rum 1 och 2. Tisdag: rum 4 och 5. Onsdag: entrén, tvättrum/toalett och städskrubbar. Torsdag: kontoret, valvet, gången genom katthemmet och omklädningsrum.',
  'Fredag: storstäda rum 6. Lördag: rum 3 och 7. Söndag: köket och se över karantänen. Alla dagar: se över om något behöver städas och töm återvinningen.',
  'Överlämning sker på plats med whiteboardtavlan. Läs tavlan när du kommer och skriv viktig information till nästa pass där. Mediciner hanteras enligt papperslistan på katthemmet.'
 ]],
 ['Praktisk information, dörrkod och introduktion',[
  'Välj ditt katthem när du loggar in. Katthemmet överst på sidan styr schema, volontärlista, nyheter, praktisk information, adress och dörrkod. Bara tilldelade katthem går att öppna. Huskvarna och Jönköping är samma katthem. Fritext i en äldre profil ger inte åtkomst till ett annat katthem.',
  'Adress och hitta hit finns här under Praktisk information. Katthemmets adress och dörrkod visas i den första rutan på bokningssidan för inloggade användare.',
  'Min första tid på katthemmet är en personlig checklista för nya volontärer. Gå igenom den med en erfaren volontär. Kryss sparas automatiskt och kan tas bort. Alla punkter krävs för grönmarkering. Checklistan finns kvar även när du är grön; tar du bort ett kryss upphör grönmarkeringen tills checklistan är klar igen. Admin och superadmin är undantagna och alltid gröna.',
  'Arbetsinstruktioner och rutiner finns också analogt på katthemmet. Följ instruktionerna där och fråga när något är oklart.'
 ]],
 ['Volontärer, styrelse och administratörer',[
  'Alla på katthemmet är volontärer. På sidan Volontärer finns en fällbar lista med styrelsen först, övriga administratörer därefter och sedan djurvårdsutbildade volontärer. Alla inloggade ser namn, roll, utbildningsmarkering och telefonnummer. Saknas telefonnummer visas Kontakta via Messenger. En person visas bara en gång, och styrelsemedlemmar samt admins som gått utbildningen har markeringen Djurvårdsutbildad.',
  'Styrelseuppdrag och administratörsbehörighet är separata uppgifter. Medlemsregister ingår inte i volontärmodulen.',
  'Kontakta via Messenger är klickbar när en personlig Messenger-länk finns i profilen. Utan angiven länk är det en texthänvisning; sök då personen i Messenger. Om både telefon och Messenger-länk finns visas båda. Bemanningsgruppens Messenger-länk är ännu inte inlagd.',
  'Under Praktisk information finns Kontaktpersoner med styrelsen och djurvårdsutbildade. Där visas namn, uppdrag, katthem och telefonnummer. Saknas telefonnummer kontaktar du personen via Messenger.',
  'Den fullständiga volontärslistan, födelsedatum och andra privata profiluppgifter visas bara för admin och superadmin.'
 ]],
 ['Mitt konto och glömt lösenord',[
  'Byt lösenord under Mitt konto genom att ange ditt nuvarande och ett nytt lösenord med 10–200 tecken.',
  'Glömt lösenord? på inloggningssidan skickar en återställningslänk till kontots e-postadress när e-postfunktionen är aktiverad. Länken gäller i 30 minuter och kan användas en gång. Kontrollera skräpposten och be annars admin om hjälp.',
  'Logga ut när du är klar, särskilt på en delad dator. På mobil finns utloggning under Mitt konto.'
 ]]
 ];
 if(admin)chapters.push(
 ['Flytta volontärer mellan katthem',[
 'Admin kan använda Administration → Skapa och planera → Flytta volontär mellan hem där admin har administratörsbehörighet i både det gamla och det nya hemmet. Vanlig åtkomst som volontär räcker inte. Bara ordinarie volontärkonton utan adminbehörighet kan flyttas av admin.',
 'Förhandsgranska flytten. Volontären måste först kontrollera och avboka kommande pass. Antal genomförda pass och lösenord följer med, men checklistan börjar om och grönmarkeringen kräver en klar checklista i det nya hemmet.',
 'Om personen har kopplingar till katthem utanför ditt administrativa område, eller har administratörsbehörighet, behöver superadmin hjälpa till. Tilldelning av åtkomst och skapande av katthem är fortsatt superadmins uppgift.'
 ]],
 ['Administration och bemanning',[
  'Administration är uppdelad i fällbara avsnitt. Öppna det avsnitt du behöver; öppna avsnitt behålls vid automatisk uppdatering under samma sidbesök.',
  'Bemanning visar kommande pass idag och sex dagar framåt, med veckonummer och tydlig avdelare vid veckobyte. Pass som redan har börjat och inställda pass tas inte med.',
  'Standardurvalet visar pass med färre än två bokade eller utan grönmarkerad person. Visa alla pass växlar till samtliga pass under samma sjudagarsperiod. Hantera pass öppnar bokning och deltagare.',
  'Volontärer att följa upp i Administration visar aktiva volontärer som saknar avslutat pass under 60 dagar. Nya konton får 60 dagars starttid. Det är stöd för kontakt, inte närvaroregistrering.'
 ]],
 ['Skapa, ändra och ställa in pass',[
  'Administration → Skapa och planera → Skapa extra pass skapar ett engångspass eller en serie. Välj En gång, Varje vecka, Varannan vecka eller Var fjärde vecka.',
  'Återkommande extra pass får ett slutdatum högst ett år efter startdatum och förhandsgranskas innan de skapas. Redan befintliga pass med samma datum och tid samt inställda söndagspass hoppas över. Inga volontärer bokas automatiskt.',
  'Varje skapat tillfälle kan ändras eller ställas in separat. Detta skiljer sig från Boka återkommande, som bokar en person på redan befintliga pass inom det öppna schemat.',
  'Skapa händelse används exempelvis för ett veterinärbesök. Volontärer kan boka sig själva även på extra pass, händelser, öppet hus och volontärsträffar.',
  'Extra information i passdialogen kan redigeras av admin och superadmin, även för öppet hus. Volontärsträffens knapp heter Information om träffen. Informationen visas i schemat, detaljerna och kalenderposterna.',
  'Ändra / boka om flyttar ett pass och behåller bokningarna. Överlappande bokningar kräver bekräftelse. Ställ in behåller deltagarna i historiken men stoppar nya bokningar och påminnelser. Boka om kan återaktivera ett inställt tillfälle.',
  'Öppet hus skapas automatiskt första söndagen varje månad 11–15 och ligger fast. Volontärsträff skapas efteråt 15–16 och kan redigeras, flyttas eller ställas in utan att återskapas.',
  'Avslutade pass kan inte ändras. Vid ändrade eller inställda pass köas mejl till berörda aktiva deltagare när e-post är aktiverad.'
 ]],
 ['Nyheter: publicera, tidsbegränsa och radera',[
  'Administration → Nyheter och anslagstavla → Skapa nyhet öppnar formuläret. Fyll i rubrik och text.',
  'Välj 1, 3, 7, 14 eller 30 dagar eller ett eget slutdatum och klockslag. Visningstid är obligatorisk vid publicering. Markera Publicera på startsidan och anslagstavlan och spara. Avmarkering sparar nyheten utan att visa den för volontärerna.',
  'Alla inloggade kan dölja nyheten för sitt konto på startsidan. På Anslagstavla ligger den kvar för alla fram till sluttiden; där kan läsaren inte klicka bort den. Sluttiden tar bort nyheten från båda vyerna. Avpublicera tar bort visningen utan att radera nyheten ur administrationen.',
  'Admin och superadmin kan välja Radera vid en nyhet och bekräfta. Det tar permanent bort nyheten och dess läsarmarkeringar, även om den redan har gått ut. Använd Avpublicera om texten ska sparas.',
  'Äldre nyheter utan sluttid har sparats som utkast och visas inte förrän admin väljer visningstid och publicerar igen. Innehållet behålls.',
  'Redigera och spara ger en ny version som visas igen även för dem som dolt den tidigare versionen. Om någon annan redan ändrat nyheten behöver du öppna den igen innan du sparar.'
 ]],
 ['Hantera volontärprofiler',[
  'Volontärer visar först den gemensamma styrelse-/administratörslistan och därefter den privata volontärslistan. Sök på namn, e-post, roll eller ansvar och filtrera på utbildning, grönmarkering eller kontostatus.',
  'Volontärslistan och grupperna med ansvariga visas i två kolumner på större skärmar och i en kolumn på små mobilskärmar. Även Visa volontärprofil och Redigera volontärprofil använder två kolumner; redigeringen är indelad i Kontakt, katthem och inloggning samt Uppdrag och övrig volontärsinformation. Volontärkorten är kompakta och sökning samt filter fungerar som vanligt.',
  'Lägg till volontär öppnar ett gemensamt formulär för personuppgifter, kontakt, uppdrag och inloggning. Ange e-post och tillfälligt lösenord när en ny volontär läggs till. Allt sparas tillsammans utan en separat kontopost i gränssnittet.',
  'Volontärmodulen innehåller inga medlemsuppgifter. Tidigare medlemsmarkering, medlemsnummer, medlemsdatum och hemadress tas bort ur de aktiva databaserna vid uppdateringen. Äldre exporter och säkerhetskopior behöver hanteras enligt föreningens gallringsrutiner. Ett framtida medlemsregister är en separat, valbar modul och ingår inte här.',
  'Engagemang (Aktiv, Pausad, Inaktiv eller Avslutad) ändras under Administration → Engagemang, introduktion och gallring. Får logga in är en separat inloggningsspärr. Paus och avslut spärrar nya bokningar men tillåter inloggning före gallring för att hantera sitt engagemang.',
  'Varje konto får en profil eller kopplas till en befintlig profil med samma unika e-post. Namn och e-post delas med kontot; bokningar och behörigheter behålls. Om flera äldre profiler har samma e-post görs ingen automatisk koppling; kontrollera dubbletterna innan uppgifterna ändras.',
  'Äldre volontärer som ännu saknar inloggning kompletteras i samma redigeringsformulär med e-post och tillfälligt lösenord. Befintliga lösenord och bokningar behålls när andra uppgifter ändras.',
  'För en klickbar Messenger-kontakt: öppna Volontärer → Visa volontärprofil → Redigera volontärprofil. Fyll i Messenger-länk, exempelvis https://m.me/anvandarnamn, och spara. Använd personens riktiga länk från Messenger, inte exempeladressen. HTTPS-länkar till m.me, messenger.com och facebook.com/messages/t/ stöds.',
  'Länken används i kontaktlistorna på Volontärer och Praktisk information. Saknas telefon används länken för Kontakta via Messenger; utan länk visas samma text utan klickfunktion. Finns både telefon och länk visas båda. Töm fältet för att ta bort länken. Gruppens Messenger-länk kan läggas till senare och hanteras inte av detta profilfält.',
  'Ange vilket katthem personen arbetar på och markera Har gått djurvårdsutbildningen när utbildningen är genomgången. Utbildningen syns på profilen och kan filtreras i volontärslistan. Styrelseuppdrag och utbildningsmarkering styr kontaktlistan under Praktisk information; aktiva och stödjande profiler med aktiva konton visas där, liksom profiler utan konto.',
  'Födelsedatum är frivilligt och privat. Under Administration → Födelsedagar visas idag och innevarande vecka, måndag–söndag. Avslutade profiler tas inte med; födelsedag den 29 februari visas under skottår.'
 ]],
 ['Inloggning och grönmarkering i volontärhanteringen',[
  'På sidan Volontärer väljer du Lägg till volontär. Ange namn, e-post och ett tillfälligt lösenord med 10–200 tecken. Lämna uppgifterna personligen; inget välkomstmejl skickas.',
  'Öppna Visa volontärprofil → Redigera volontärprofil för att ändra kontaktuppgifter och inloggning tillsammans. Lämna lösenordsfältet tomt för att behålla det nuvarande lösenordet. Genvägar för inloggning finns också på respektive volontärkort. Byt lösenord sätter ett nytt lösenord och avslutar personens befintliga inloggningar. Personen kan sedan byta lösenord under Mitt konto.',
  'Inaktivera stoppar inloggning men behåller bokningar och profil. Gå igenom kommande pass när ett konto inaktiveras. Aktivera öppnar kontot igen.',
  'Grönmarkera ger manuell grönmarkering. Markeringen får effekt först när checklistan är klar. Ta bort manuell grönmarkering tar inte bort automatisk grönmarkering vid minst 10 pass och klar checklista. Admin och superadmin är alltid gröna.',
  'Antalet genomförda pass visas på kortet och i profilen. Det räknas från avslutade bokningar, inte från registrerad närvaro.',
  'Admin hanterar volontärkonton. Superadmin hanterar också administratörers konton, lösenord och roller. Vanlig admin kan redigera övriga profiluppgifter men inte ändra administratörers namn och e-post via profilen.'
 ]],
 ['Import, export och insamling av uppgifter',[
  'Administration → Importera och exportera CSV → Importera från CSV tar emot nya volontärkonton. Förhandsgranska innan kontona skapas. Befintliga konton uppdateras inte av importen.',
  'Använd UTF-8, semikolon eller komma och rubrikerna namn;e-post;lösenord samt valfritt grön. Högst 500 personer och 500 kB per fil. E-post ska vara unik och lösenord ha 10–200 tecken.',
  'Grönmarkera alla i importen gäller samtliga rader. Annars används kolumnen grön med ja eller nej. Alla importerade konton får volontärbehörighet och kopplas till profiler. De blir gröna först när hela checklistan är genomförd, även om grön är markerat i importen. Inga inloggningsuppgifter skickas automatiskt.',
  'Exportera till CSV hämtar schema och bokningar med semikolon som avgränsare. Automatisk synkning med Google Sheets är inte ansluten.',
  'Fullständiga volontärprofiler har ännu ingen CSV-import. Använd insamlingsrubrikerna i Samla in uppgifter längre ned i manualen och för över profiluppgifterna via volontärformuläret.'
 ]],
 ['Påminnelser och ändringsmejl',[
  'Egna bokningar inom nästa dygn ger en påminnelse på sidan. Aktiverad e-post används även för påminnelser inom 24 timmar före passet, ändringar, inställda pass och lösenordsåterställning.',
  'Administration → E-post och påminnelser visar om utskick är aktiverade, väntande ändringsmejl och eventuella misslyckade försök. Skicka påminnelser för nästa dygn startar en kontroll av aktuella bokningar.',
  'Superadmin hanterar e-postinställningarna. Servern behöver vara igång för automatiska utskick och återförsök. Kalenderappens aviseringar är separata från portalens e-post.'
 ]],
 ['Redigera adress och dörrkod',[
  'Praktisk information → Redigera information ändrar Adress och hitta hit för alla inloggade. Adressen används också i nya kalenderfiler och kalenderprenumerationen.',
  'I Veckoschema väljer du Ändra dörrkod vid dörrkodsrutan. Ändringen gäller bara det katthem som är valt överst på sidan. Endast admin och superadmin kan spara en ny kod. Den visas för inloggade användare och läggs inte i kalenderposter eller e-post.',
  'Om en annan administratör hunnit ändra dörrkoden behöver du öppna formuläret igen innan du sparar.'
 ]]
 );
 if(state.portal?.global_superadmin)chapters.push(['Katthem och åtkomst',[
 'Administration → Skapa och planera → Hantera katthem och åtkomst öppnar registret. Lägg till katthemmets namn och adress. Det nya hemmet får egen databas, eget schema och tom volontärlista, nyheter och dörrkod. E-postinställningar och CSV-utskick delas inte mellan hemmen.',
 'Alla tidigare uppgifter ligger kvar under Huskvarna / Jönköping. Superadmin i det ursprungliga katthemmet har åtkomst till samtliga katthem. Välj hem överst på sidan; adress, kod, bokningar och exporter gäller det valda hemmet.',
 'Tilldela åtkomst: välj personens ordinarie konto och ett annat katthem, välj Admin eller Volontär och spara. Styrelseuppdrag anges separat i profilen och ger inte automatiskt tillgång till andra hem. Personen loggar fortsatt in i sitt ordinarie katthem och kan därefter växla till tilldelade hem. Personen syns direkt i det tilldelade hemmet utan att behöva logga in där först. Styrelseuppdrag, telefon, Messenger-länk och utbildningsmarkering följer med; privata anteckningar, födelsedatum och hemadress kopieras inte. Lokala ändringar i det andra hemmets profil bevaras.',
 'Återkalla tar bort extra åtkomst direkt och behåller historik. Det ordinarie hemmet styrs av kontots aktivering där. Uppdrag och statistik hör till respektive hem. Ett konto med samma e-post i ett annat hem kopplas aldrig automatiskt ihop.',
 'Flytta volontär finns i samma vy. Välj ordinarie konto och nytt katthem och förhandsgranska. Flytten stoppas om personen har kommande eller pågående pass i gamla hemmet eller andra hem där extra åtkomst avslutas. Volontären behöver själv kontrollera och avboka passen först; vid sena förhinder används bemanningsgruppen i Messenger.',
 'Profil, lösenord och totalantal genomförda pass följer med. Bokningar kopieras aldrig mellan scheman. Tidigare pass räknas bara en gång även om personen flyttas tillbaka. Checklistan börjar om i det nya hemmet, även för tidigare gröna volontärer. Manuell grönmarkering sparas men gäller först när den nya checklistan är klar.',
 'Efter bekräftad flytt avslutas gamla inloggningar, kalenderlänkar och extra tilldelningar. Personen väljer det nya katthemmet vid inloggning och skapar ny kalenderprenumeration. Gamla pass finns kvar i historiken. Adminbehörighet, styrelseuppdrag och lokala ansvarsområden följer inte med; dessa tilldelas separat. Superadminkonton kan inte flyttas.',
 'Om en tidigare profil för samma person finns i målkatthemmet visas en varning före bekräftelse: profiluppgifterna uppdateras men bokningshistoriken behålls. Ett orelaterat konto med samma e-post blockerar flytten; det slås aldrig ihop automatiskt.',
 'Systemets superadminkonton skapas och hanteras under det ursprungliga katthemmet. Adminrättigheter kan tilldelas separat för andra hem.',
 'Lösenord byts för det ordinarie kontot även när ett annat hem är valt. Personliga kalenderprenumerationer och CSV-exporter hör till ett hem. Länkar ger aldrig dörrkod. Komplett säkerhetskopiering behöver omfatta hela data-mappen, inklusive shelters.sqlite och underkatalogerna för katthem.'
 ]]);
 if(state.portal?.global_superadmin)chapters.push(['Gemensamma nyheter för flera katthem',[
 'Administration → Gemensamma nyheter → Skapa gemensam nyhet. Välj Alla katthem för information om systemuppdateringar, eller Valda katthem och kryssa i mottagarna. Alla katthem inkluderar även katthem som läggs till senare under nyhetens visningstid.',
 'Ange rubrik, text och en obligatorisk visningstid: ett antal dagar eller eget slutdatum och tid. Nyheten visas över kalendern och på anslagstavlan i berörda hem. Läsaren kan dölja den på startsidan men den ligger kvar på anslagstavlan till sluttiden.',
 'Bara superadmin kan skapa, redigera, avpublicera och radera gemensamma nyheter. Avmarkera Publicera och spara för att avpublicera. En ändrad version visas igen för läsare som dolt den tidigare. Lokala admins hanterar fortfarande bara sina egna lokala nyheter.'
 ]]);
 if(superadmin)chapters.push(
 ['Superadmin: roller och administratörskonton',[
  'På sidan Volontärer väljer du Lägg till volontär. Som superadmin kan du välja Volontär eller Admin under Behörighet i samma formulär. Systemets Superadmin väljs i det ursprungliga katthemmet. Egen behörighet och aktivering ändras inte där.',
  'Gör till admin, Gör till volontär och Gör till superadmin på volontärkortet ändrar en annan persons behörighet efter bekräftelse. Styrelseuppdrag anges separat i volontärprofilen.',
  'Du kan hantera administratörers lösenord och aktivering. Din egen roll eller aktivering ändras inte från kontokortet; eget lösenord ändras under Mitt konto.'
 ]],
 ['Superadmin: aktivera och kontrollera e-post',[
  'Administration → E-post och påminnelser → E-postinställningar öppnar Gmail-inställningarna. Ange Gmail-adress, Google-applösenord och portalens publika webbadress.',
  'Använd ett applösenord, inte Gmail-kontots vanliga lösenord. Spara och använd Skicka testmejl för att kontrollera leveransen. Aktivera Gmail för påminnelser, ändringsmejl och lösenordsåterställning.',
  'Ett tomt applösenordsfält behåller det sparade värdet. Byte av Gmail-adress kräver ett nytt applösenord. Det sparade applösenordet visas inte igen.',
  'I samma e-postformulär aktiverar du automatiska CSV-utskick och väljer dagligen, varje vecka eller varje månad. Mottagare är alltid den sparade Gmail-adressen. Både Gmail och CSV-utskick behöver vara aktiverade. Första utskicket sker efter ett intervall från aktiveringen; varje vecka betyder sju dagar. Vid månadsintervall används nästa månad och sista dagen om samma datum saknas.',
  'CSV-status visar senaste lyckade och nästa planerade utskick samt eventuellt fel. Skicka CSV nu använder sparade inställningar och fungerar även när automatiken är avstängd, om Gmail är aktiverat. Ett lyckat manuellt utskick räknas som senaste utskick. Misslyckade automatiska utskick försöker igen tidigast efter en timme. Servern måste vara igång; efter avbrott skickas en aktuell export när den är förfallen.',
  'CSV-filerna innehåller personuppgifter från profilerna samt konton, pass, bokningar, praktisk information och introduktionskryss. Id-kolumner binder ihop filerna; schema- och träffursprung bevaras. Filerna är UTF-8 med semikolon. Automatisk återimport finns inte. Lösenord, e-postnycklar, dörrkod och privata kalenderlänkar exporteras inte; lösenord måste återställas om konton återskapas. CSV ersätter inte en fullständig databasbackup.',
  'Avmarkera Aktivera automatiska CSV-utskick och spara för att stoppa schemat. Om Gmail också ska stängas av, avmarkera båda inställningarna. Tidigare skickade mejl finns kvar i inkorgen.',
  'Kontrollera att sidans webbadress är den publicerade HTTPS-adressen. Avmarkera aktivering för att stoppa utskick. Redan sparade inställningar och köer finns kvar.'
 ]]
 );
 const title=superadmin?'Manual för superadmin':admin?'Manual för admin':'Manual för volontärer';
 return `<section class="panel portal-manual"><h2>${title}</h2><p class="muted">Genomgången för version 0.6.007. Öppna det avsnitt du behöver. Innehållet anpassas efter din behörighet.</p>${chapters.map(([heading,steps])=>`<details><summary>${esc(heading)}</summary><ol>${steps.map(step=>`<li>${esc(step)}</li>`).join('')}</ol></details>`).join('')}${registrationGuide()}</section>`;
}

function editVolunteerInfo(){show(`<h2>Praktisk information</h2><p class="small">Visas för inloggade volontärer. Lämna fält tomma tills informationen är klar.</p><form id="info-form">${infoFields.map(([key,title])=>`<label>${title}<textarea name="${key}" rows="4" maxlength="4000">${esc(state.shelter_admin?.[key]??state.volunteer_info?.[key]??'')}</textarea></label>`).join('')}<p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara</button></div></form>`);$('#info-form').onsubmit=e=>{e.preventDefault();mutate('volunteer-info','PUT',Object.fromEntries(new FormData(e.target)),'Informationen har sparats.')}}
async function calendarSubscription(){try{const result=await api('calendar/subscription','POST');show(`<h2>Prenumerera på mina pass</h2><p>Lägg till länken en gång som kalenderprenumeration i din kalenderapp. Dina bokningar, ändrade tider och avbokningar hämtas sedan automatiskt. Uppdateringen kan dröja beroende på kalenderappen.</p><p>Kalenderposterna innehåller en påminnelse 12 timmar före passet. Kalenderappen avgör hur den hanteras; kontrollera aviseringarna där. Restid och avresepåminnelse ställer du in i din kalenderapp med katthemmets adress som plats.</p><label>Din privata kalenderlänk<input id="calendar-url" type="url" readonly value="${esc(result.url)}"></label><p class="small">I Google Kalender: Andra kalendrar → + → Från webbadress. I Apple Kalender och Outlook: välj att prenumerera på en kalender från en webbadress. Att importera en fil ger bara en kopia.</p><p class="notice">Länken ger tillgång till dina pass utan inloggning. Dela den inte med andra. Om länken börjar med 127.0.0.1 fungerar den bara på den här datorn; en extern kalender kräver länken från den publicerade sidan.</p><p id="calendar-subscription-status" role="status"></p><div class="dialog-actions"><button id="copy-calendar-url">Kopiera länk</button><button class="danger" id="revoke-calendar-url">Återkalla länken</button><button data-close>Stäng</button></div>`);$('#copy-calendar-url').onclick=async()=>{try{await navigator.clipboard.writeText(result.url);$('#calendar-subscription-status').textContent='Länken har kopierats.'}catch{$('#calendar-url').select();$('#calendar-subscription-status').textContent='Kopiera den markerade länken.'}};$('#revoke-calendar-url').onclick=()=>{show('<h2>Återkalla kalenderlänken?</h2><p>Den gamla länken slutar fungera och kalenderapparna slutar få uppdateringar. Redan hämtade poster kan finnas kvar. Du kan sedan skapa en ny länk och lägga till den i kalenderappen.</p><div class="dialog-actions"><button id="confirm-revoke-calendar">Återkalla länken</button><button data-close>Avbryt</button></div>');$('#confirm-revoke-calendar').onclick=async()=>{try{await api('calendar/subscription','DELETE');modal.close();toast('Kalenderlänken är återkallad.')}catch(e){toast(e.message)}}}}catch(e){toast(e.message)}}
function calendarLink(s){const b=state.bookings.find(b=>b.slot_id===s.id&&b.user_id===state.user.id);return b&&!s.cancelled?`<a class="export-link" title="Kalenderfilen är en kopia och uppdateras inte automatiskt vid ändringar." href="/api/bookings/${b.id}/calendar">Lägg till i kalender</a>`:''}
function cancelledBookings(){const slots=state.slots.filter(s=>s.mine&&s.cancelled&&new Date(s.date+'T'+s.end)>new Date());return slots.length?`<section class="panel"><h2>Inställda pass</h2>${slots.map(s=>`<div class="list-row"><div><strong>${esc(s.title)}</strong><p>${fmt(s.date)} · ${s.start}–${s.end} · Inställt</p></div><button data-slot="${s.id}">Visa information</button></div>`).join('')}</section>`:''}
function forgotPassword(){show(`<h2>Glömt lösenord?</h2><p>Ange din e-postadress för att få en återställningslänk. Länken gäller i 30 minuter.</p><form id="forgot-form"><label>E-post<input name="email" type="email" autocomplete="username" maxlength="254" required></label><p class="error" role="alert"></p><p id="reset-status" role="status"></p><div class="dialog-actions"><button type="button" data-close>Stäng</button><button class="primary">Skicka länk</button></div></form>`);$('#forgot-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('.primary');button.disabled=true;try{const result=await api('password-reset/request','POST',Object.fromEntries(new FormData(e.target)));$('#reset-status').textContent=result.message}catch(err){modal.querySelector('.error').textContent=err.message}finally{button.disabled=false}}}
function resetPassword(token){show(`<h2>Välj nytt lösenord</h2><form id="reset-form"><label>Nytt lösenord<input name="password" type="password" autocomplete="new-password" minlength="10" maxlength="200" required></label><label>Bekräfta lösenord<input name="confirm" type="password" autocomplete="new-password" minlength="10" maxlength="200" required></label><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara lösenord</button></div></form>`);$('#reset-form').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target)),button=e.target.querySelector('.primary');if(values.password!==values.confirm){modal.querySelector('.error').textContent='Lösenorden stämmer inte överens.';return}button.disabled=true;try{await api('password-reset/confirm','POST',{token,password:values.password});modal.close();state=null;login();toast('Lösenordet har ändrats. Logga in med ditt nya lösenord.')}catch(err){modal.querySelector('.error').textContent=err.message;button.disabled=false}}}
let refreshing=false;
async function refreshSchedule(manual=false){
 if(!state||refreshing||modal.open||checklistSaving.size||document.visibilityState==='hidden')return;
 refreshing=true;const version=mutationVersion;
 try{const fresh=await api('state');if(!state||modal.open||version!==mutationVersion)return;state=fresh;if(['schedule','mine'].includes(view)){const scroll=window.scrollY;render();window.scrollTo(0,scroll)}if(manual)toast('Schemat är uppdaterat.')}catch(err){if(manual)toast(err.message);else if($('#refresh-status'))$('#refresh-status').textContent='Kunde inte uppdatera · '}
 finally{refreshing=false}
}
setInterval(()=>refreshSchedule(),30000);
window.addEventListener('focus',()=>refreshSchedule());
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')refreshSchedule()});
let resetLinkActive=false;
function openResetLink(){const token=new URLSearchParams(window.location.hash.slice(1)).get('reset');if(!token)return false;resetLinkActive=true;portalHomeHint=portalLoginShelter();mutationVersion++;history.replaceState(null,'',window.location.pathname);state=null;view='schedule';login();if(modal.open)modal.close();resetPassword(token);return true}
window.addEventListener('hashchange',openResetLink);
const memberStatusLabel=status=>({active:'Aktiv',supporting:'Stödjande',paused:'Vilande',ended:'Avslutad'}[status]||status);
const boardRoleLabel=m=>({none:'Ingen styrelseroll',chair:'Ordförande',vice_chair:'Vice ordförande',treasurer:'Kassör',secretary:'Sekreterare',member:'Ledamot',deputy:'Suppleant',other:m.board_title}[m.board_role]||m.board_role);
function accountActions(u){if(u.transfer_retired)return '<p class="small">Flyttad till annat katthem · historiken är bevarad</p>';if(u.portal_managed)return '';return `<div class="actions">${u.id!==state.user.id&&canManageAccount(state.user,u)?`<button data-reset-password="${u.id}">Byt lösenord</button>`:''}${isSuperAdmin(state.user)&&u.id!==state.user.id?`<button data-role-user="${u.id}" data-role="${u.role==='admin'?'volunteer':'admin'}">${u.role==='admin'?'Gör till volontär':'Gör till admin'}</button>`:''}${isSuperAdmin(state.user)&&(!state.portal||state.portal.selected==='huskvarna')&&u.id!==state.user.id&&u.role!=='superadmin'?`<button data-role-user="${u.id}" data-role="superadmin">Gör till superadmin</button>`:''}${u.role==='volunteer'?`<button data-green-user="${u.id}" data-green="${u.green_manual?'false':'true'}">${u.green_manual?'Ta bort manuell grönmarkering':'Grönmarkera'}</button>`:''}${u.id!==state.user.id&&canManageAccount(state.user,u)?`<button data-user="${u.id}" data-active="${u.active?0:1}">${u.active?'Inaktivera':'Aktivera'}</button>`:''}</div>`}
let volunteerSearch='',volunteerFilter='all';
function leadershipPanel(){const people=state.leadership||(state.members||[]).flatMap(m=>{const account=state.users.find(u=>u.id===m.user_id);return m.board_role!=='none'||isAdmin(account)||m.animal_care_trained?[{...m,role:account?.role||'volunteer'}]:[]}),board=people.filter(m=>m.board_role!=='none'),admins=people.filter(m=>m.board_role==='none'&&isAdmin(m)),trained=people.filter(m=>m.board_role==='none'&&!isAdmin(m)&&m.animal_care_trained),row=(m,role)=>`<div class="list-row"><div><strong>${esc(m.name)}</strong><p>${esc(role)}</p>${m.animal_care_trained?'<span class="badge">Djurvårdsutbildad</span>':''}<p class="contact-phone">${m.phone?esc(m.phone):messengerContact(m)}${m.phone&&m.messenger_url?' · '+messengerContact(m):''}</p></div></div>`;return `<details class="admin-section" data-admin-section="leadership"><summary>Styrelse, administratörer och djurvårdsutbildade (${people.length})</summary><div class="admin-section-body"><h2>Styrelsen</h2>${board.length?`<div class="leadership-grid">${board.map(m=>row(m,boardRoleLabel(m))).join('')}</div>`:'<p>Ingen styrelseroll har angetts ännu.</p>'}<h2>Övriga administratörer</h2>${admins.length?`<div class="leadership-grid">${admins.map(m=>row(m,m.role==='superadmin'?'Superadmin':'Admin')).join('')}</div>`:'<p>Inga övriga administratörer.</p>'}<h2>Djurvårdsutbildade volontärer</h2>${trained.length?`<div class="leadership-grid">${trained.map(m=>row(m,'Volontär')).join('')}</div>`:'<p>Inga ytterligare djurvårdsutbildade volontärer är markerade ännu.</p>'}</div></details>`}
function membersPage(){const admin=isAdmin(state.user),people=(state.members||[]).filter(m=>!state.users.find(u=>u.id===m.user_id)?.transfer_retired);return `<div class="eyebrow">VOLONTÄRER</div><h1>Volontärer</h1><p class="muted">Här finns katthemmets volontärer, styrelse, administratörer och djurvårdsutbildade.</p>${leadershipPanel()}${admin?`<section class="panel"><h2>Volontärslista</h2><p class="small">Privata profiler och kontohantering visas bara för admin och superadmin.</p><div class="actions"><button class="primary" data-new-member>+ Lägg till volontär</button></div><div class="toolbar"><label class="member-search">Sök volontär<input id="member-search" type="search" value="${esc(volunteerSearch)}" placeholder="Namn, katthem, e-post, roll eller ansvar…"></label><label>Filtrera<select id="volunteer-filter">${[['all','Alla'],['trained','Djurvårdsutbildade'],['green','Grönmarkerade'],['accounts','Inloggning skapad'],['noaccount','Inloggning väntar'],['active','Får logga in'],['inactive','Inloggning avstängd']].map(([value,label])=>`<option value="${value}" ${volunteerFilter===value?'selected':''}>${label}</option>`).join('')}</select></label></div><p id="member-search-empty" class="muted" hidden>Inga volontärer matchar urvalet.</p>${state.users.some(u=>!people.some(m=>m.user_id===u.id))?'<p class="notice">Det finns äldre profiler med samma e-post som behöver kontrolleras innan de kan kopplas automatiskt.</p>':''}<div class="member-grid">${people.map(m=>{const u=state.users.find(u=>u.id===m.user_id);return `<article class="panel member-card ${u?.green?'experienced-volunteer':''}" data-member-card data-profile-id="${m.id}" data-search="${esc([m.name,m.email,m.phone,m.shelter,boardRoleLabel(m),m.responsibilities,u?.role].join(' ').toLocaleLowerCase('sv-SE'))}"><h2>${esc(m.name)}</h2><span class="badge">Volontär</span>${m.animal_care_trained?'<span class="badge">Djurvårdsutbildad</span>':''}<p class="small">Katthem: ${esc(m.shelter)||'Ej angivet'}</p>${m.board_role!=='none'?`<p class="member-board-role">${esc(boardRoleLabel(m))}</p>`:''}<p class="small">${esc(m.email)||'E-post ej angiven'}${m.phone?' · '+esc(m.phone):''}</p><p class="member-text">${esc(m.responsibilities)||'Inget ytterligare ansvar angivet.'}</p><p class="small">${u?u.completed_shifts+' genomförda pass · '+(u.role==='volunteer'?(u.checklist_complete?'Checklista klar · ':'Checklista ej klar · '):'')+(isAdmin(u)?u.role==='superadmin'?'Superadmin':'Admin':u.active?'Aktivt volontärkonto':'Inaktivt volontärkonto'):'Inloggning väntar'}</p><button data-member-profile="${m.id}">Visa volontärprofil</button>${u?accountActions(u):''}</article>`}).join('')}</div></section>`:'<p class="small">Volontärernas privata profiler hanteras av admin och superadmin.</p>'}`}
function filterMembers(value=volunteerSearch){volunteerSearch=value;let visible=0;app.querySelectorAll('[data-member-card]').forEach(card=>{const m=(state.members||[]).find(m=>m.id===Number(card.dataset.profileId)),u=state.users.find(u=>u.id===m?.user_id);const matches=volunteerFilter==='all'||volunteerFilter==='trained'&&m?.animal_care_trained||volunteerFilter==='green'&&u?.green||volunteerFilter==='accounts'&&u||volunteerFilter==='noaccount'&&!u||volunteerFilter==='active'&&u?.active||volunteerFilter==='inactive'&&u&&!u.active;card.hidden=!matches||!card.dataset.search.includes(value.trim().toLocaleLowerCase('sv-SE'));if(!card.hidden)visible++});if($('#member-search-empty'))$('#member-search-empty').hidden=visible>0||!(state.members||[]).length}
function memberProfile(id){const m=state.members.find(m=>m.id===id);
 show(`<div class="volunteer-profile-dialog"><div class="eyebrow">VOLONTÄRPROFIL</div><h2>${esc(m.name)}</h2><span class="badge">Volontär</span><dl class="member-details profile-details-grid"><div class="profile-detail"><dt>Katthem</dt><dd>${esc(m.shelter)||'Ej angivet'}</dd></div><div class="profile-detail"><dt>Djurvårdsutbildning</dt><dd>${m.animal_care_trained?'Genomgången':'Ej markerad'}</dd></div><div class="profile-detail"><dt>Födelsedatum</dt><dd>${m.birth_date?fmt(m.birth_date,{day:'numeric',month:'long',year:'numeric'}):'Ej angivet'}</dd></div><div class="profile-detail"><dt>Genomförda pass</dt><dd>${m.user_id?state.users.find(u=>u.id===m.user_id)?.completed_shifts||0:'Inloggning väntar'}</dd></div><div class="profile-detail"><dt>Inloggning</dt><dd>${m.user_id?esc(state.users.find(u=>u.id===m.user_id)?.email||'Kopplat konto'):'Inget konto kopplat'}</dd></div><div class="profile-detail"><dt>E-post</dt><dd>${esc(m.email)||'Ej angivet'}</dd></div><div class="profile-detail"><dt>Telefon</dt><dd>${esc(m.phone)||'Ej angivet'}</dd></div><div class="profile-detail"><dt>Messenger</dt><dd>${messengerContact(m)}</dd></div><div class="profile-detail"><dt>Styrelseroll</dt><dd>${esc(boardRoleLabel(m))}</dd></div><div class="profile-detail"><dt>Ytterligare ansvar</dt><dd>${esc(m.responsibilities)||'Inget angivet'}</dd></div><div class="profile-detail"><dt>Övrig information</dt><dd>${esc(m.note)||'Ingen angiven'}</dd></div></dl><p class="small">Uppdaterat ${new Date(m.updated_at).toLocaleString('sv-SE')}</p><div class="dialog-actions"><button data-close>Stäng</button><button class="primary" id="edit-member-profile">Redigera profil</button></div></div>`);$('#edit-member-profile').onclick=()=>memberForm(id);
}
function formValue(form,name,fallback){const field=form.elements[name];return field&&!field.disabled?field.value:fallback}
function memberForm(id,initialRole='volunteer'){
 const m=id?state.members.find(m=>m.id===id):{name:'',email:'',phone:'',status:'active',board_role:'none',board_title:'',responsibilities:'',note:'',messenger_url:'',shelter:'',birth_date:'',animal_care_trained:false};
 const linkedAccount=state.users.find(u=>u.id===m.user_id),protectedContact=linkedAccount&&!canManageAccount(state.user,linkedAccount),self=linkedAccount?.id===state.user.id;
 show(`<div class="volunteer-profile-dialog"><h2>${id?'Redigera volontärprofil':'Lägg till volontär'}</h2><form id="member-form"><div class="profile-form-grid"><section class="profile-form-column"><h3>Kontakt, katthem och inloggning</h3>
 <label>Namn<input name="name" value="${esc(m.name)}" ${protectedContact?'readonly':''} required maxlength="100" autocomplete="name"></label>
 <label>E-post<input name="email" value="${esc(m.email)}" ${protectedContact?'readonly':''} type="email" ${!id?'required':''} maxlength="254" autocomplete="email"></label>
 <label>Telefon<input name="phone" value="${esc(m.phone)}" type="tel" maxlength="100" autocomplete="tel"></label>
 <label>Messenger-länk (valfritt)<input name="messenger_url" type="url" maxlength="500" value="${esc(m.messenger_url||'')}" placeholder="https://m.me/anvandarnamn"></label>
 <label>Katthem som volontären arbetar på<input name="shelter" value="${esc(state.portal?state.shelter.name:m.shelter||'')}" ${state.portal?'readonly':''} maxlength="150" placeholder="Katthemmets namn eller ort"></label>
 <label>Födelsedatum (valfritt)<input name="birth_date" type="date" value="${m.birth_date||''}" max="${dateStr(new Date())}"></label>
 <h3>Inloggning</h3><label>Behörighet<select name="account_role" ${linkedAccount?.portal_managed||!isSuperAdmin(state.user)||self?'disabled':''}>${(isSuperAdmin(state.user)?(state.portal&&state.portal.selected!=='huskvarna'?['volunteer','admin']:['volunteer','admin','superadmin']):[linkedAccount?.role||'volunteer']).map(role=>`<option value="${role}" ${(linkedAccount?.role||initialRole)===role?'selected':''}>${roleLabel(role)}</option>`).join('')}</select></label><label class="check-label"><input name="account_active" type="checkbox" ${!linkedAccount||linkedAccount.active?'checked':''} ${linkedAccount?.transfer_retired||linkedAccount?.portal_managed||protectedContact||self?'disabled':''}> Får logga in</label>${!linkedAccount?.portal_managed&&!self&&!protectedContact?`<label>${linkedAccount?'Nytt lösenord (valfritt)':'Tillfälligt lösenord'}<input name="account_password" type="password" autocomplete="new-password" minlength="10" maxlength="200" ${!id?'required':''}></label><p class="small">${linkedAccount?'Lämna tomt för att behålla lösenordet. Ett nytt lösenord avslutar tidigare inloggningar.':'Ange e-post och ett tillfälligt lösenord för att ge inloggning. Lämna uppgifterna personligen.'}</p>`:'<p class="small">Eget lösenord byts under Mitt konto. Endast superadmin kan ändra andra administratörers inloggning.</p>'}<label class="check-label"><input name="account_green" type="checkbox" ${linkedAccount?.green_manual?'checked':''} ${linkedAccount?.portal_managed||protectedContact||linkedAccount&&linkedAccount.role!=='volunteer'?'disabled':''}> Manuellt grönmarkerad</label></section>
 <section class="profile-form-column"><h3>Uppdrag och övrig volontärsinformation</h3>
 <input type="hidden" name="status" value="${esc(m.status)}"><p class="small">Engagemang, paus och avslut ändras under Administration → Engagemang, introduktion och gallring.</p>
 <label>Roll i styrelsen<select name="board_role">${['none','chair','vice_chair','treasurer','secretary','member','deputy','other'].map(role=>`<option value="${role}" ${m.board_role===role?'selected':''}>${role==='other'?'Annan styrelseroll':boardRoleLabel({board_role:role})}</option>`).join('')}</select></label>
 <label>Annan styrelseroll (om vald ovan)<input name="board_title" value="${esc(m.board_title)}" maxlength="100"></label>
 <label class="check-label"><input name="animal_care_trained" type="checkbox" ${m.animal_care_trained?'checked':''}> Har gått djurvårdsutbildningen</label>
 <label>Ytterligare ansvarsområden<textarea name="responsibilities" maxlength="2000" rows="2" placeholder="Till exempel volontärsamordning, inköp eller veterinärkontakt.">${esc(m.responsibilities)}</textarea></label>
 <label>Övrig volontärsinformation<textarea name="note" maxlength="3000" rows="2">${esc(m.note)}</textarea></label><p class="small">Skriv bara arbetsrelaterad information som behövs för volontäruppdraget, inga medlemsuppgifter eller hemadresser.</p></section></div>
 <p class="small">Styrelsen och djurvårdsutbildade visas för inloggade med uppdrag och kontaktuppgifter. Ange personens riktiga Messenger-länk; utan länk visas en texthänvisning. Volontären har en gemensam post med kontaktuppgifter och inloggning. Engagemang, paus och avslut hanteras separat; Får logga in styr inloggningen. Volontären kan ändra egna grunduppgifter under Mitt konto. Övriga privata uppgifter hanteras av admin och superadmin.</p>
 <p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara volontär</button></div></form></div>`);
 $('#member-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button.primary');button.disabled=true;const payload=Object.fromEntries(new FormData(e.target));payload.animal_care_trained=e.target.elements.animal_care_trained.checked;payload.account={role:formValue(e.target,'account_role',linkedAccount?.role||initialRole),password:e.target.elements.account_password?.value||'',active:e.target.elements.account_active.checked,green:e.target.elements.account_green.checked};delete payload.account_role;delete payload.account_password;delete payload.account_active;delete payload.account_green;if(id)payload.revision=m.revision;await mutate(id?'volunteers/'+id:'volunteers',id?'PUT':'POST',payload,'Volontären har sparats.');if(modal.open)button.disabled=false};
}

function doorCodePanel(){const info=state.door_code;return `<section class="stat door-code-panel" aria-label="Dörrkod"><div><div class="eyebrow">TILLTRÄDE TILL KATTHEMMET</div><h2>Dörrkod</h2>${state.shelter?`<p class="small">${esc(state.shelter.name)}</p>`:''}<p class="door-code-value">${info?.code?esc(info.code):'<span class="muted">'+(state.shelter?.configured===false?'Katthemmet saknar kopplad dörrkod. Kontakta admin.':'Ingen dörrkod har lagts in ännu.')+'</span>'}</p>${state.volunteer_info?.location?`<p class="small">${esc(state.volunteer_info.location)}</p>`:''}${info?.updated_at?`<span class="small">Uppdaterad ${new Date(info.updated_at).toLocaleString('sv-SE')}</span>`:''}</div>${isAdmin(state.user)?'<button id="edit-door-code">Ändra dörrkod</button>':''}</section>`}
function editDoorCode(){const info=state.shelter_admin?.door||state.door_code||{code:'',revision:0};show(`<h2>Ändra dörrkod</h2><form id="door-code-form"><label>Dörrkod<input name="code" value="${esc(info.code)}" maxlength="80" autocomplete="off"></label><p class="small">Koden visas för inloggade användare vid veckoschemat. Endast admin och superadmin kan ändra den. Lämna tomt för att ta bort koden.</p><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara dörrkod</button></div></form>`);$('#door-code-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('button.primary');button.disabled=true;const values=Object.fromEntries(new FormData(e.target));await mutate('door-code','PUT',{code:values.code,revision:info.revision},'Dörrkoden har uppdaterats.');if(modal.open)button.disabled=false;else modal.innerHTML=''}}


api('portal').then(data=>{portalDirectory=data}).catch(()=>{}).finally(()=>{if(!openResetLink())api('state').then(s=>{if(!resetLinkActive){state=s;render()}}).catch(()=>{if(!resetLinkActive)login()})});

function portalLoginShelter(){const selected=typeof document!=='undefined'?$('#login-shelter')?.value:null;return selected||portalHomeHint||new URLSearchParams(window.location.search||'').get('shelter')||portalDirectory?.default_shelter||''}
async function manageShelters(){try{const data=await api('portal/manage');show(`<h2>Katthem och åtkomst</h2><p>Superadmin har tillgång till samtliga katthem. Övriga har sitt ordinarie hem och uttryckligen tilldelad åtkomst.</p><h3>Lägg till katthem</h3><form id="portal-new-shelter"><label>Namn<input name="name" required maxlength="100"></label><label>Adress<textarea name="address" maxlength="4000" required></textarea></label><button class="primary">Skapa katthem</button></form><hr><h3>Tilldela åtkomst till ett annat katthem</h3><form id="portal-access"><label>Ordinarie konto<select name="person" required><option value="">Välj person…</option>${data.users.filter(u=>u.active&&!(u.source==='huskvarna'&&u.role==='superadmin')).map(u=>`<option value="${esc(u.source+':'+u.id)}">${esc(u.name)} · ${esc(u.email)} · ${esc(data.shelters.find(h=>h.id===u.source)?.name)}</option>`).join('')}</select></label><label>Katthem<select name="target">${data.shelters.map(h=>`<option value="${esc(h.id)}">${esc(h.name)}</option>`).join('')}</select></label><label>Behörighet<select name="role"><option value="admin">Admin / styrelse</option><option value="volunteer">Volontär</option></select></label><button class="primary">Spara åtkomst</button></form><h3>Flytta volontär till ett annat katthem</h3><form id="portal-transfer"><label>Ordinarie konto<select name="person" required><option value="">Välj person…</option>${data.users.filter(u=>u.active&&u.role!=='superadmin').map(u=>`<option value="${esc(u.source+':'+u.id)}">${esc(u.name)} · ${esc(data.shelters.find(h=>h.id===u.source)?.name)}</option>`).join('')}</select></label><label>Nytt katthem<select name="target">${data.shelters.map(h=>`<option value="${esc(h.id)}">${esc(h.name)}</option>`).join('')}</select></label><p class="small">Volontären behöver först kontrollera och avboka kommande pass. Genomförda pass räknas med i det nya hemmet, men checklistan börjar om. Flytten förhandsgranskas innan du bekräftar.</p><button>Förhandsgranska flytt</button></form><h3>Tilldelad extra åtkomst</h3>${data.grants.map(g=>{const u=data.users.find(u=>u.source===g.source&&u.id===g.user_id);return `<div class="list-row"><div><strong>${esc(u?.name||'Inaktivt konto')}</strong><p>${esc(data.shelters.find(h=>h.id===g.target)?.name)} · ${g.role==='admin'?'Admin':'Volontär'}</p></div><button data-revoke-access="${esc(g.source+':'+g.user_id+':'+g.target)}">Återkalla</button></div>`}).join('')||'<p>Ingen extra åtkomst tilldelad.</p>'}<p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Stäng</button></div>`);
 const save=async(route,payload)=>{try{await api(route,'POST',payload);state=await api('state');render();await manageShelters()}catch(err){modal.querySelector('.error').textContent=err.message}};
 $('#portal-new-shelter').onsubmit=async e=>{e.preventDefault();e.target.querySelector('button').disabled=true;await save('portal/manage/shelters',Object.fromEntries(new FormData(e.target)));if($('#portal-new-shelter'))$('#portal-new-shelter').querySelector('button').disabled=false};
 $('#portal-transfer').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target)),[source,id]=values.person.split(':');previewVolunteerTransfer({source,user_id:Number(id),target:values.target},data.shelters)};
 $('#portal-access').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target)),[source,id]=values.person.split(':');save('portal/manage/grants',{source,user_id:Number(id),target:values.target,role:values.role,enabled:true})};
 modal.querySelectorAll('[data-revoke-access]').forEach(b=>b.onclick=()=>{const [source,id,target]=b.dataset.revokeAccess.split(':');save('portal/manage/grants',{source,user_id:Number(id),target,role:'admin',enabled:false})});
 }catch(err){toast(err.message)}}

function portalRequestShelter(url){return state?.portal?.selected||(url.startsWith('password-reset/')?portalLoginShelter():'')}
async function previewVolunteerTransfer(payload,houses){try{const p=await api((state.portal?.global_superadmin?'portal/manage/transfers':'portal/transfers')+'/preview','POST',payload);show(`<h2>Flytta ${esc(p.name)}?</h2><p>Från ${esc(houses.find(h=>h.id===p.source)?.name)} till ${esc(houses.find(h=>h.id===p.target)?.name)}.</p><p>Profil och befintligt lösenord följer med. Genomförda pass räknas även i det nya hemmet. Gamla bokningsposter ligger kvar i det gamla hemmet. Checklistan nollställs i det nya hemmet; grönmarkering börjar gälla först när den är klar.</p><p>Åtkomst till det gamla hemmet och tidigare extra tilldelningar avslutas. Volontären loggar in på det nya katthemmet och skapar en ny kalenderprenumeration där. Styrelseuppdrag, lokalansvar och adminbehörighet följer inte med.</p>${p.reuses_profile?'<p class="notice">Personen har tidigare funnits i det nya hemmet. Kontakt- och volontärsuppgifterna ersätts med uppgifterna från den aktuella profilen. Befintlig bokningshistorik behålls.</p>':''}${p.future.length?`<h3>Volontären behöver avboka dessa pass först</h3>${p.future.map(s=>`<p>${esc(s.home_name)} · ${esc(s.date)} · ${esc(s.start)}–${esc(s.end)} · ${esc(s.title)}</p>`).join('')}`:''}${p.ongoing?'<p class="notice">Ett pass pågår. Vänta tills det är avslutat.</p>':''}<p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Avbryt</button><button class="primary" id="confirm-volunteer-transfer" ${p.can_move?'':'disabled'}>Bekräfta flytt</button></div>`);$('#confirm-volunteer-transfer').onclick=async e=>{e.target.disabled=true;try{const result=await api(state.portal?.global_superadmin?'portal/manage/transfers':'portal/transfers','POST',{...payload,key:p.key});state=await api('state');modal.close();render();toast('Volontären har flyttats. '+result.completed_shifts+' genomförda pass följer med.')}catch(err){modal.querySelector('.error').textContent=err.message;e.target.disabled=false}}}catch(err){modal.querySelector('.error').textContent=err.message}}
function portalNewsPanel(){if(!state.portal?.global_superadmin)return '';return `<details class="admin-section" data-admin-section="portal-news"><summary>Gemensamma nyheter – alla eller valda katthem</summary><div class="admin-section-body"><p>Publicera systemuppdateringar till alla katthem eller välj vilka hem som ska få en nyhet. Samma nyhet visas över kalendern och på respektive anslagstavla till sluttiden.</p><button class="primary" data-action="new-portal-news">+ Skapa gemensam nyhet</button>${(state.portal_news_admin||[]).map(n=>`<div class="list-row"><div><strong>${esc(n.title)}</strong><p class="small">${n.all_shelters?'Alla katthem, även framtida':n.targets.map(id=>state.portal.shelters.find(h=>h.id===id)?.name||id).map(esc).join(', ')} · ${!n.published?'Avpublicerad / utkast':n.expires_at<=Date.now()?'Utgången':'Publicerad'}</p></div><div class="actions"><button data-edit-portal-news="${n.id}">Redigera</button><button data-delete-portal-news="${n.id}">Radera</button></div></div>`).join('')}</div></details>`}
async function dismissPortalNews(id,button){const item=state.news.find(n=>n.id==='p'+id);button.disabled=true;try{await api('portal/news/'+id+'/dismiss','POST',{revision:item.revision});state=await api('state');render()}catch(err){toast(err.message);button.disabled=false}}
function portalNewsForm(id){const n=id?state.portal_news_admin.find(n=>n.id===id):{title:'',body:'',expires_at:null,published:true,all_shelters:1,targets:[]};const local=t=>{const d=new Date(t);return dateStr(d)+'T'+String(d.getHours()).padStart(2,'0')+':'+String(d.getMinutes()).padStart(2,'0')};show(`<h2>${id?'Redigera':'Skapa'} gemensam nyhet</h2><form id="portal-news-form"><label>Rubrik<input name="title" value="${esc(n.title)}" required maxlength="150"></label><label>Text<textarea name="body" required maxlength="4000" rows="5">${esc(n.body)}</textarea></label><label>Målgrupp<select name="audience" id="portal-news-audience"><option value="all" ${n.all_shelters?'selected':''}>Alla katthem, även framtida</option><option value="selected" ${n.all_shelters?'':'selected'}>Valda katthem</option></select></label><fieldset id="portal-news-targets" ${n.all_shelters?'hidden':''}><legend>Välj katthem</legend>${state.portal.shelters.map(h=>`<label class="check-label"><input type="checkbox" name="target" value="${esc(h.id)}" ${n.targets.includes(h.id)?'checked':''}> ${esc(h.name)}</label>`).join('')}</fieldset><label>Visningstid<select id="portal-news-duration" required><option value="" disabled ${!n.expires_at?'selected':''}>Välj…</option>${[1,3,7,14,30].map(d=>`<option value="${d}">${d} dagar</option>`).join('')}<option value="custom" ${n.expires_at?'selected':''}>Välj slutdatum och tid</option></select></label><label>Slutar visas<input id="portal-news-expires" name="expires" type="datetime-local" value="${n.expires_at?local(n.expires_at):''}" ${n.expires_at?'required':'disabled'}></label><label class="check-label"><input name="published" type="checkbox" ${n.published?'checked':''}> Publicera på startsidor och anslagstavlor</label><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara nyhet</button></div></form>`);$('#portal-news-audience').onchange=e=>$('#portal-news-targets').hidden=e.target.value==='all';$('#portal-news-duration').onchange=e=>{const input=$('#portal-news-expires');input.disabled=false;input.required=true;input.value=e.target.value==='custom'?'':local(Date.now()+Number(e.target.value)*86400000)};$('#portal-news-form').onsubmit=async e=>{e.preventDefault();const f=e.target.elements,targets=[...e.target.querySelectorAll('input[name="target"]:checked')].map(i=>i.value);try{await api('portal/manage/news'+(id?'/'+id:''),id?'PUT':'POST',{title:f.title.value,body:f.body.value,all_shelters:f.audience.value==='all',targets,published:f.published.checked,expires_at:f.expires.value?new Date(f.expires.value).getTime():null,...(id?{revision:n.revision}:{})});state=await api('state');modal.close();render();toast('Nyheten har sparats.')}catch(err){modal.querySelector('.error').textContent=err.message}}}
function deletePortalNews(id){const n=state.portal_news_admin.find(n=>n.id===id);show(`<h2>Radera gemensam nyhet?</h2><p>”${esc(n.title)}” tas bort från samtliga berörda katthem.</p><p class="error" role="alert"></p><div class="dialog-actions"><button data-close>Avbryt</button><button class="primary" id="confirm-delete-portal-news">Radera nyheten</button></div>`);$('#confirm-delete-portal-news').onclick=async()=>{try{await api('portal/manage/news/'+id,'DELETE',{revision:n.revision});state=await api('state');modal.close();render()}catch(err){modal.querySelector('.error').textContent=err.message}}}
async function adminTransferVolunteers(){try{const data=await api('portal/transfers');show(`<h2>Flytta volontär</h2><p>Välj en volontär och ett annat katthem som du administrerar. Kommande bokningar behöver avbokas före flytten.</p><form id="admin-volunteer-transfer"><label>Volontär<select name="person" required><option value="">Välj…</option>${data.users.map(u=>`<option value="${esc(u.source+':'+u.id)}">${esc(u.name)} · ${esc(data.shelters.find(h=>h.id===u.source)?.name)}</option>`).join('')}</select></label><label>Nytt katthem<select name="target">${data.shelters.map(h=>`<option value="${esc(h.id)}">${esc(h.name)}</option>`).join('')}</select></label><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Förhandsgranska flytt</button></div></form>`);$('#admin-volunteer-transfer').onsubmit=e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),[source,id]=f.person.split(':');previewVolunteerTransfer({source,user_id:Number(id),target:f.target},data.shelters)}}catch(err){toast(err.message)}}
const engagementLabel=s=>({active:'Aktiv',paused:'Pausad',inactive:'Inaktiv',ended:'Avslutad',purged:'Gallrad'}[s]||s);
const engagementDate=t=>t?new Date(t).toLocaleDateString('sv-SE'):'–';
function engagementPanel(){const e=state.user.engagement;if(!e)return '';return `<section class="panel"><h2>Mitt engagemang</h2><p><strong>${engagementLabel(e.status)}</strong> · ${esc(state.shelter.name)}</p>${e.review_at?`<p>Uppföljning av paus: ${engagementDate(e.review_at)}</p>`:''}${e.purge_after?`<p>Planerad gallring: ${engagementDate(e.purge_after)}${e.held?' · Undantag behöver prövas av admin.':''}</p>`:''}<p>Paus behåller dina uppgifter och har ett uppföljningsdatum. Avslut startar tre månaders frist före gallring. Kontrollera och avboka kommande pass först.</p>${!e.can_self_book&&e.status==='active'?'<p class="notice">Självständig bokning väntar på introduktion eller bekräftelse av aktuella rutiner. Gå till Praktisk information. Admin kan boka introduktionspass tillsammans med en handledare.</p>':''}<button data-engagement-self>Ändra mitt engagemang</button></section>`}
function routinePanel(){const r=state.routine,e=state.user.engagement;if(!r)return '';return `<section class="panel"><h2>Aktuella rutiner${r.version?' · version '+r.version:''}</h2>${r.version?`<h3>${esc(r.title)}</h3><p class="info-text">${esc(r.body)}</p><p class="small">Publicerade ${engagementDate(r.published_at)}</p>${e?.routine_current?`<p>✓ Bekräftat ${engagementDate(e.routine_accepted_at)}</p>`:'<button data-accept-routines>Jag har läst och förstått rutinerna</button>'}`:'<p>Inga digitala rutiner har publicerats ännu. Arbetsinstruktionerna finns på katthemmet.</p>'}${isAdmin(state.user)?'<button data-edit-routines>Publicera ny rutinversion</button>':''}${e?.needs_intro?`<p>Introduktion: checklista ${e.checklist_complete?'klar':'väntar'} · praktisk introduktion ${e.practical_completed?'klar':'väntar'} · självständig bokning ${e.independent_approved?'godkänd':'väntar på admin'}.</p>`:''}</section>`}
function engagementAdminPanel(){const rows=state.users.filter(u=>u.engagement&&!u.transfer_retired);return `<details class="admin-section" data-admin-section="engagement"><summary>Engagemang, introduktion och gallring</summary><div class="admin-section-body"><p>Frånvaro i 60 dagar är en uppföljningssignal och ändrar ingen status automatiskt. Paus och inaktivitet leder inte till gallring. Ett uttryckligt avslut startar tre kalendermånader.</p>${rows.map(u=>{const e=u.engagement;return `<div class="list-row"><div><strong>${esc(u.name)}</strong><p>${engagementLabel(e.status)}${e.review_at?' · Pausuppföljning '+engagementDate(e.review_at):''}${e.purge_after?' · Gallring '+engagementDate(e.purge_after):''}</p>${e.review_due?'<p class="notice">Pausen behöver följas upp.</p>':''}${e.purge_warning?'<p class="notice">Gallring närmar sig. Kontrollera om ett dokumenterat annat ändamål finns.</p>':''}${e.held&&e.status==='ended'?`<p class="notice">Gallring spärrad: ${esc(e.hold_reason)}</p>`:''}<p class="small">Rutiner: ${e.routine_version||'ej bekräftade'} · Introduktion: ${e.intro_ready?'klar':'väntar'}</p></div>${canManageAccount(state.user,u)?`<div class="actions"><button data-engagement-user="${u.id}">Ändra status</button><button data-introduction-user="${u.id}">Introduktion</button><button data-hold-user="${u.id}">Gallringsundantag</button></div>`:''}</div>`}).join('')}</div></details>`}
function editEngagement(uid,self=false){const u=self?state.user:state.users.find(u=>u.id===uid),e=u.engagement;show(`<h2>${self?'Mitt engagemang':esc(u.name)}</h2><form id="engagement-form"><label>Status<select name="status">${(self?['active','paused','ended']:['active','paused','inactive','ended']).map(s=>`<option value="${s}" ${e.status===s?'selected':''}>${engagementLabel(s)}</option>`).join('')}</select></label>${self&&state.portal?'<label>Gäller<select name="scope"><option value="one">Det valda katthemmet</option><option value="all">Hela föreningen – alla mina katthem</option></select></label>':''}<label>Uppföljningsdatum (krävs vid paus)<input type="date" name="review_date" value="${e.review_at?new Date(e.review_at).toISOString().slice(0,10):''}"></label><p>Kommande och pågående pass måste hanteras före paus eller avslut. Avslut leder till gallring efter tre kalendermånader; en varning visas för admin ungefär två veckor före. Gallrade uppgifter kan inte återställas.</p><label class="check-label"><input type="checkbox" name="confirm" required> Jag har kontrollerat valet och förstår följderna.</label><p class="error" role="alert"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara</button></div></form>`);$('#engagement-form').onsubmit=async event=>{event.preventDefault();const p=Object.fromEntries(new FormData(event.target));delete p.confirm;p.revision=e.revision;try{await api(self?(state.portal?'portal/engagement':'engagement'):'engagements/'+uid,'PATCH',p);state=await api('state');modal.close();render();toast('Engagemanget har uppdaterats.')}catch(error){modal.querySelector('.error').textContent=error.message}}}
function editIntroduction(uid){const u=state.users.find(u=>u.id===uid),e=u.engagement;show(`<h2>Introduktion – ${esc(u.name)}</h2><p>Checklistan och aktuell rutinbekräftelse krävs före godkännande av självständig bokning. Godkännandet är separat från grönmarkering.</p><form id="intro-form"><label class="check-label"><input type="checkbox" name="practical_completed" ${e.practical_completed?'checked':''}> Praktisk introduktion genomförd</label><label class="check-label"><input type="checkbox" name="independent_approved" ${e.independent_approved?'checked':''}> Godkänd för självständig bokning</label><p class="error"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara</button></div></form>`);$('#intro-form').onsubmit=event=>{event.preventDefault();mutate('engagements/'+uid+'/introduction','PATCH',{practical_completed:event.target.practical_completed.checked,independent_approved:event.target.independent_approved.checked},'Introduktionen har uppdaterats.')}}
function editHold(uid){const e=state.users.find(u=>u.id===uid).engagement;show(`<h2>Dokumenterat gallringsundantag</h2><p>Registrera endast ett annat konkret ändamål som motiverar fortsatt lagring, och när behovet ska prövas igen. Administratörsuppdrag måste också avslutas separat. Lämna skälet tomt för att ta bort undantaget.</p><form id="hold-form"><label>Skäl<textarea name="reason" maxlength="500">${esc(e.held?e.hold_reason:'')}</textarea></label><label>Prövas igen<input name="until" type="date" value="${e.hold_until?new Date(e.hold_until).toISOString().slice(0,10):''}"></label><p class="error"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Spara</button></div></form>`);$('#hold-form').onsubmit=event=>{event.preventDefault();mutate('engagements/'+uid+'/hold','PATCH',Object.fromEntries(new FormData(event.target)),'Undantaget har uppdaterats.')}}
function editRoutines(){const r=state.routine;show(`<h2>Publicera ny rutinversion</h2><p>Alla volontärer på detta katthem behöver bekräfta den nya versionen innan de bokar självständigt.</p><form id="routine-form"><label>Rubrik<input name="title" required maxlength="150" value="${esc(r.title)}"></label><label>Rutiner<textarea name="body" required maxlength="12000" rows="12">${esc(r.body)}</textarea></label><p class="error"></p><div class="dialog-actions"><button type="button" data-close>Avbryt</button><button class="primary">Publicera version ${r.version+1}</button></div></form>`);$('#routine-form').onsubmit=event=>{event.preventDefault();mutate('routines','PUT',{...Object.fromEntries(new FormData(event.target)),version:r.version},'En ny rutinversion har publicerats.')}}
function ownProfilePanel(){const p=state.my_profile;if(!p)return '';const identity=state.portal?.profile_identity_editable!==false;return `<section class="panel"><h2>Min profil</h2><form id="own-profile-form"><div class="profile-form-grid"><section class="profile-form-column"><label>Namn<input name="name" required maxlength="100" value="${esc(p.name)}" ${identity?'':'disabled'}></label><label>E-post för inloggning<input name="email" type="email" required maxlength="254" value="${esc(p.email)}" ${identity?'':'disabled'}></label><label>Telefon<input name="phone" type="tel" maxlength="100" value="${esc(p.phone)}"></label></section><section class="profile-form-column"><label>Messenger-länk<input name="messenger_url" type="url" maxlength="500" value="${esc(p.messenger_url)}" placeholder="https://m.me/anvandarnamn"></label><label>Födelsedatum (valfritt)<input name="birth_date" type="date" max="${dateStr(new Date())}" value="${esc(p.birth_date)}"></label></section></div>${!identity?'<p class="small">Namn och inloggningsadress ändras i ditt ordinarie katthem. Övriga uppgifter gäller det valda hemmet.</p>':''}<p class="error" role="alert"></p><button class="primary">Spara min profil</button></form></section>`}
